INSERT INTO public.contributeurs (id, code, nom_complet, nom_court, email_principal, type_contributeur, statut, biographie, affiliation_principale, pays_iso3, url_publique, orcid, domaines_expertise, date_premier_engagement, date_dernier_engagement, notes_internes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (1, 'siba_kalivogui', 'Siba Kalivogui', NULL, 'editeur.principal@kuma-science.org', 'editeur_principal', 'actif', NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-01', NULL, NULL, true, NULL, '2026-09-17 06:04:10.525564+00', NULL, '2026-09-17 06:04:10.525564+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (1, 'seconde', 'seconde', 's', 'temps', 'SI', true, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Unité SI de base pour la grandeur temps. Définie depuis 1967 par la fréquence de la transition hyperfine de l''atome de césium 133 : ΔνCs = 9 192 631 770 Hz exactement. Confirmée par la révision SI 2019.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 2","13ème CGPM (1967), résolution 1","26ème CGPM (2018)","ISO 80000-3"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (2, 'minute', 'minute', 'min', 'temps', 'non_SI_acceptee', false, 60.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Unité non-SI acceptée pour usage avec le SI selon le Tableau 8 de la brochure BIPM. Définie comme exactement 60 secondes.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (3, 'heure', 'heure', 'h', 'temps', 'non_SI_acceptee', false, 3600.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Unité non-SI acceptée pour usage avec le SI selon le Tableau 8 de la brochure BIPM. Définie comme exactement 3600 secondes.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (4, 'jour', 'jour', 'jour', 'temps', 'non_SI_acceptee', false, 86400.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Unité non-SI acceptée pour usage avec le SI selon le Tableau 8 de la brochure BIPM. Définie comme exactement 86400 secondes (24 heures × 3600 s). Symbole francophone "jour" préféré au "d" (day).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (5, 'annee_calendaire', 'année calendaire', 'a', 'temps', 'non_SI_acceptee', false, 31556952.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Année calendaire grégorienne moyenne selon convention IUPAC (Green Book 1993) : 365,2425 jours = 31 556 952 secondes exactement. Cette convention diffère légèrement de l''année julienne UAI (365,25 j = 31 557 600 s, écart 0,07%) et de l''année tropique (365,24219 j, écart 0,000086%). Convention Kuma : utilisation systématique de l''année grégorienne moyenne IUPAC pour cohérence avec les rapports IEA/IRENA.', NULL, '{"IUPAC Green Book 1993","IUPAP Red Book","BIPM SI Brochure 9ème édition (2019)","UAI Style Manual 1989"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (6, 'metre', 'mètre', 'm', 'longueur', 'SI', true, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre', 'Unité SI de base pour la longueur. Définie depuis 1983 par la fixation exacte de la vitesse de la lumière dans le vide à c = 299 792 458 m/s, où la seconde est définie par la fréquence du césium 133. Première unité SI définie par une constante fondamentale, ouvrant la voie à la révision SI 2019.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 2","17ème CGPM (1983), Résolution 1","26ème CGPM (2018)","ISO 80000-3"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (7, 'kilometre', 'kilomètre', 'km', 'longueur', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre', 'Multiple SI du mètre avec le préfixe kilo (10³). Massivement utilisée pour les distances en Afrique : longueurs de lignes électriques (interconnexions régionales 100-1500 km), distances entre villes, surfaces administratives.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (8, 'centimetre', 'centimètre', 'cm', 'longueur', 'SI', false, 0.010000000000000000000000000000, 0.000000000000000000000000000000, 'metre', 'Sous-multiple SI du mètre avec le préfixe centi (10⁻²).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (9, 'millimetre', 'millimètre', 'mm', 'longueur', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'metre', 'Sous-multiple SI du mètre avec le préfixe milli (10⁻³). Très utilisé pour les sections de câbles, épaisseurs de modules PV, précipitations annuelles.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (10, 'kilogramme', 'kilogramme', 'kg', 'masse', 'SI', true, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme', 'Unité SI de base pour la masse. Définie depuis la révision SI 2019 par la fixation exacte de la constante de Planck à h = 6,62607015 × 10⁻³⁴ J·s. Particularité : seule unité SI de base ayant un préfixe (kilo) dans son nom, héritage historique du « grave » de la Révolution française.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 2","26ème CGPM (2018), résolution 1"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (11, 'gramme', 'gramme', 'g', 'masse', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme', 'Sous-multiple du kilogramme. Anomalie historique : les préfixes SI s''appliquent au gramme et non au kilogramme (mg, g, kg, etc.) bien que le kilogramme soit l''unité SI de base.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (12, 'tonne', 'tonne', 't', 'masse', 'non_SI_acceptee', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme', 'Unité non-SI acceptée pour usage avec le SI selon le Tableau 8 de la brochure BIPM. Définie comme exactement 1000 kilogrammes. Largement utilisée pour les bilans de matières et de combustibles à grande échelle.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (13, 'ampere', 'ampère', 'A', 'courant_electrique', 'SI', true, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'ampere', 'Unité SI de base pour le courant électrique. Définie depuis la révision SI 2019 par la fixation exacte de la charge élémentaire à e = 1,602176634 × 10⁻¹⁹ C. Cette définition rend l''ampère dérivé de la seconde et de la charge élémentaire.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 2","26ème CGPM (2018), résolution 1"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (14, 'milliampere', 'milliampère', 'mA', 'courant_electrique', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'ampere', 'Sous-multiple SI de l''ampère.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (15, 'kiloampere', 'kiloampère', 'kA', 'courant_electrique', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'ampere', 'Multiple SI de l''ampère, utilisé pour les forts courants industriels.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (16, 'kelvin', 'kelvin', 'K', 'temperature', 'SI', true, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kelvin', 'Unité SI de base pour la température thermodynamique. Définie depuis la révision SI 2019 par la fixation exacte de la constante de Boltzmann à k = 1,380649 × 10⁻²³ J/K. Échelle absolue : 0 K = zéro absolu (pas de température négative en kelvin). Conditions STC photovoltaïque : 25°C = 298,15 K.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 2","26ème CGPM (2018), résolution 1","ISO 80000-5"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (17, 'degree_celsius', 'degré Celsius', '°C', 'temperature', 'SI', false, 1.000000000000000000000000000000, 273.150000000000000000000000000000, 'kelvin', 'Unité SI dérivée avec nom spécial selon le Tableau 4 de la brochure BIPM. Définie par t = T − T₀ où T₀ = 273,15 K exactement. SEULE unité SI avec un décalage de conversion non nul vers l''unité de base. ATTENTION : la formule T_K = T_°C + 273,15 ne s''applique qu''aux températures absolues. Pour les différences (ΔT), 1 °C = 1 K.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4","ISO 80000-5"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (18, 'degree_fahrenheit', 'degré Fahrenheit', '°F', 'temperature', 'imperial', false, 0.555555555555555555555555555556, 255.372222222222222222222222222222, 'kelvin', 'Unité de température du système impérial américain. Définition exacte : 32 °F = 0 °C = 273,15 K (fusion de la glace), 212 °F = 100 °C = 373,15 K (ébullition à 1 atm). Conversion vers kelvin : T_K = T_°F × 5/9 + (273,15 − 32 × 5/9) = T_°F × 0,5556 + 255,3722. CAS PÉDAGOGIQUE UNIQUE : seule unité de Kuma combinant facteur ≠ 1 ET décalage ≠ 0.', NULL, '{"ISO 80000-5","NIST Special Publication 811","ASTM E380"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (19, 'joule', 'joule', 'J', 'energie', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Unité SI dérivée avec nom spécial pour l''énergie, le travail et la chaleur (Tableau 4 BIPM). 1 J = 1 N·m = 1 W·s = kg·m²·s⁻². ALIAS SÉMANTIQUES : couvre travail (mécanique) et chaleur (thermodynamique) qui sont la même grandeur physique.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4","ISO 80000-5"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (20, 'kilojoule', 'kilojoule', 'kJ', 'energie', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule avec préfixe kilo (10³).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (21, 'megajoule', 'mégajoule', 'MJ', 'energie', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule (10⁶). Standard international IEA/IRENA pour exprimer les pouvoirs calorifiques en MJ/kg.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (22, 'gigajoule', 'gigajoule', 'GJ', 'energie', 'SI', false, 1000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule (10⁹). Utilisé pour les bilans énergétiques industriels.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (23, 'terajoule', 'térajoule', 'TJ', 'energie', 'SI', false, 1000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule (10¹²). Utilisé pour les statistiques énergétiques nationales.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (24, 'petajoule', 'pétajoule', 'PJ', 'energie', 'SI', false, 1000000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule (10¹⁵). Utilisé pour les bilans énergétiques régionaux.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (25, 'exajoule', 'exajoule', 'EJ', 'energie', 'SI', false, 1000000000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple SI du joule (10¹⁸). Utilisé pour les bilans énergétiques mondiaux. La consommation mondiale d''énergie primaire est 600 EJ/an.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7","IEA World Energy Balances"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (26, 'wattheure', 'wattheure', 'Wh', 'energie', 'composee_mixte', false, 3600.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Unité d''énergie composée combinant le watt (SI) et l''heure (non-SI acceptée). 1 Wh = 1 W × 3600 s = 3600 J exactement. La plus utilisée en énergie électrique.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (27, 'kilowattheure', 'kilowattheure', 'kWh', 'energie', 'composee_mixte', false, 3600000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Unité de référence pour la facturation électrique mondiale. 1 kWh = 3,6 MJ exactement. L''unité la plus universellement comprise pour l''énergie électrique. Tarification en GNF/kWh, XOF/kWh, EUR/kWh, USD/kWh.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (28, 'megawattheure', 'mégawattheure', 'MWh', 'energie', 'composee_mixte', false, 3600000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple du wattheure (10⁶). Standard international pour les marchés énergétiques de gros (EPEX SPOT, Nord Pool, NYMEX).', NULL, '{"BIPM SI Brochure 9ème édition (2019)","IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (29, 'gigawattheure', 'gigawattheure', 'GWh', 'energie', 'composee_mixte', false, 3600000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple du wattheure (10⁹). Utilisé pour la production annuelle des centrales et les statistiques nationales.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (30, 'terawattheure', 'térawattheure', 'TWh', 'energie', 'composee_mixte', false, 3600000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple du wattheure (10¹²). Utilisé pour les bilans énergétiques nationaux et continentaux.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (31, 'tonne_equivalent_petrole', 'tonne équivalent pétrole', 'tep', 'energie', 'autre', false, 41868000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Convention AIE : 1 tep = 41,868 GJ exactement = 11 630 kWh. Équivalence énergétique d''une tonne de pétrole brut. Standard international pour les bilans énergétiques.', NULL, '{"IEA World Energy Balances","IEA Energy Statistics Manual"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
