INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (33, 'megatonne_equivalent_petrole', 'mégatonne équivalent pétrole', 'Mtep', 'energie', 'autre', false, 41868000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple de la tep (10⁶). Utilisé pour les bilans énergétiques continentaux.', NULL, '{"IEA World Energy Balances"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (34, 'tonne_equivalent_charbon', 'tonne équivalent charbon', 'tec', 'energie', 'autre', false, 29307600000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Convention ONU : 1 tec = 7 Gcal_IT = 29,3076 GJ exactement = 8 141 kWh. Équivalence énergétique d''une tonne de charbon. Standard pour les statistiques mondiales du charbon.', NULL, '{"ONU Energy Statistics Yearbook"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (35, 'kilotonne_equivalent_charbon', 'kilotonne équivalent charbon', 'ktec', 'energie', 'autre', false, 29307600000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple de la tec (10³).', NULL, '{"ONU Energy Statistics Yearbook"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
