INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (37, 'calorie_internationale', 'calorie internationale', 'cal_IT', 'energie', 'autre', false, 4.186800000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Calorie internationale (IT - International Table) définie à la 5th International Conference on Properties of Steam, Londres 1956. 1 cal_IT = 4,1868 J exactement. Convention AIE pour la tep.', NULL, '{"5th International Conference on Properties of Steam, London 1956","NIST SP 811"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (38, 'kilocalorie_internationale', 'kilocalorie internationale', 'kcal_IT', 'energie', 'autre', false, 4186.800000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple de la calorie internationale (10³).', NULL, '{"5th International Conference on Properties of Steam, London 1956"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (39, 'calorie_thermochimique', 'calorie thermochimique', 'cal_th', 'energie', 'autre', false, 4.184000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Calorie thermochimique : 1 cal_th = 4,184 J exactement. Utilisée en chimie. Différence avec calorie IT : 0,068%.', NULL, '{"NIST SP 811","IUPAC Gold Book"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (40, 'kilocalorie_thermochimique', 'kilocalorie thermochimique', 'kcal_th', 'energie', 'autre', false, 4184.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple de la calorie thermochimique (10³). Souvent utilisée en nutrition ("Calorie alimentaire" ≡ kcal_th).', NULL, '{"NIST SP 811","IUPAC Gold Book"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (41, 'btu_internationale', 'British Thermal Unit internationale', 'BTU_IT', 'energie', 'imperial', false, 1055.055852620000000000000000000000, 0.000000000000000000000000000000, 'joule', 'British Thermal Unit (IT). 1 BTU_IT = 1 055,05585262 J exactement. Standard impérial américain pour l''énergie thermique. Très utilisé dans l''industrie pétrolière et gazière américaine.', NULL, '{"NIST SP 811","API Manual of Petroleum Measurement Standards"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (42, 'kilo_btu_internationale', 'kilo BTU', 'kBTU', 'energie', 'imperial', false, 1055055.852620000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Multiple du BTU (10³).', NULL, '{"NIST SP 811"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (43, 'million_btu', 'million BTU', 'MMBTU', 'energie', 'imperial', false, 1055055852.620000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Million de BTU (notation MM = "million" en industrie pétrolière, ne pas confondre avec méga SI). Standard pour les contrats gaz naturel américains et les marchés Henry Hub.', NULL, '{"NIST SP 811","API Manual of Petroleum Measurement Standards"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (44, 'quad', 'quadrillion BTU', 'quad', 'energie', 'imperial', false, 1055055852620000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule', 'Quadrillion BTU = 10¹⁵ BTU_IT = 1,05505585262 × 10¹⁸ J exactement. Utilisé par EIA pour les bilans énergétiques américains (consommation USA 100 quad/an, soit 100 EJ/an). Note de transcription Kuma : la valeur 1,05505585262 × 10¹⁵ qui apparaît parfois dans la littérature confond le BTU lui-même (10³ J) avec le joule.', NULL, '{"EIA Annual Energy Review"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (45, 'electronvolt', 'électronvolt', 'eV', 'energie', 'non_SI_acceptee', false, 0.000000000000000000160217663400, 0.000000000000000000000000000000, 'joule', 'Énergie acquise par un électron accéléré sous une différence de potentiel de 1 V. Définition exacte depuis SI 2019 : 1 eV = 1,602176634 × 10⁻¹⁹ J (égal à la charge élémentaire en Coulomb). Utilisée en physique des semi-conducteurs (gap du silicium 1,12 eV).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8","NIST CODATA 2018","IUPAP Red Book"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (46, 'kilo_electronvolt', 'kiloélectronvolt', 'keV', 'energie', 'non_SI_acceptee', false, 0.000000000000000160217663400000, 0.000000000000000000000000000000, 'joule', 'Multiple de l''eV (10³). Utilisé en physique nucléaire et radiobiologie.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (47, 'mega_electronvolt', 'mégaélectronvolt', 'MeV', 'energie', 'non_SI_acceptee', false, 0.000000000000160217663400000000, 0.000000000000000000000000000000, 'joule', 'Multiple de l''eV (10⁶). Utilisé en physique des particules.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (48, 'watt', 'watt', 'W', 'puissance', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Unité SI dérivée avec nom spécial pour la puissance (Tableau 4 BIPM). 1 W = 1 J/s = kg·m²·s⁻³. ALIAS SÉMANTIQUE : couvre puissance_active (puissance moyenne sur une période) qui est la même grandeur physique.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (49, 'milliwatt', 'milliwatt', 'mW', 'puissance', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Sous-multiple SI du watt.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (50, 'kilowatt', 'kilowatt', 'kW', 'puissance', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Multiple SI du watt. Standard pour la facturation des appareils électriques résidentiels et industriels.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (51, 'megawatt', 'mégawatt', 'MW', 'puissance', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Multiple SI du watt (10⁶). Standard pour la puissance des centrales électriques.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (52, 'gigawatt', 'gigawatt', 'GW', 'puissance', 'SI', false, 1000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Multiple SI du watt (10⁹). Utilisé pour les capacités installées nationales.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (53, 'terawatt', 'térawatt', 'TW', 'puissance', 'SI', false, 1000000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Multiple SI du watt (10¹²). Utilisé pour les bilans mondiaux.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (54, 'cheval_vapeur_metrique', 'cheval-vapeur métrique', 'ch', 'puissance', 'autre', false, 735.498750000000000000000000000000, 0.000000000000000000000000000000, 'watt', 'Cheval-vapeur métrique selon norme DIN 66036. 1 ch = 735,49875 W exactement (basé sur 75 kgf·m/s). Utilisé en mécanique (moteurs européens). Distinct du horsepower mécanique (US).', NULL, '{"DIN 66036","NIST SP 811"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (55, 'horsepower_mecanique', 'horsepower mécanique', 'hp', 'puissance', 'imperial', false, 745.699871582270220000000000000000, 0.000000000000000000000000000000, 'watt', 'Horsepower mécanique (US). 1 hp = 745,69987158227022 W exactement (basé sur 550 ft·lbf/s). Utilisé en mécanique américaine.', NULL, '{"NIST SP 811","ASTM E380"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (56, 'watt_crete', 'watt-crête', 'Wc', 'puissance_crete_pv', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_crete', 'Puissance nominale d''un module ou système photovoltaïque dans les conditions STC (Standard Test Conditions) : irradiance 1000 W/m², spectre AM1.5, température de cellule 25°C. Le watt-crête (Wc, Wp en anglais) est sémantiquement DISTINCT du watt thermique car il caractérise une capacité solaire, pas une puissance électrique fournie au réseau. La conversion Wc → kWh dépend du facteur de capacité du site.', NULL, '{"IEC 61215-1:2021","IEC 60904-3:2019","IEC 60904-9:2020","ASTM G173-03(2020)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (57, 'kilowatt_crete', 'kilowatt-crête', 'kWc', 'puissance_crete_pv', 'composee_mixte', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_crete', 'Multiple du watt-crête (10³). Utilisé pour le PV résidentiel et commercial.', NULL, '{"IEC 61215-1:2021","IEC 60904-3:2019"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (58, 'megawatt_crete', 'mégawatt-crête', 'MWc', 'puissance_crete_pv', 'composee_mixte', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_crete', 'Multiple du watt-crête (10⁶). Utilisé pour le PV utility-scale. Exemples africains : Bokhol Sénégal 30 MWc (premier utility-scale africain), Noor Ouarzazate IV 70 MWc, Benban Égypte 1800 MWc.', NULL, '{"IEC 61215-1:2021","IRENA Country Profiles"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (59, 'gigawatt_crete', 'gigawatt-crête', 'GWc', 'puissance_crete_pv', 'composee_mixte', false, 1000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_crete', 'Multiple du watt-crête (10⁹). Utilisé pour les capacités PV nationales et continentales.', NULL, '{"IEC 61215-1:2021","IRENA Renewable Capacity Statistics"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (60, 'watt_par_metre_carre', 'watt par mètre carré', 'W/m²', 'irradiance_solaire', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_par_metre_carre', 'Unité SI de l''irradiance solaire (densité de flux radiatif). Représente la puissance solaire reçue par unité de surface. STC PV : 1000 W/m² = "Full Sun". Constante solaire au sommet de l''atmosphère : 1361 W/m² (TSI - Total Solar Irradiance, NASA).', NULL, '{"ISO 9488","ISO 9846","WMO Guide to Meteorological Instruments"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (61, 'kilowatt_par_metre_carre', 'kilowatt par mètre carré', 'kW/m²', 'irradiance_solaire', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'watt_par_metre_carre', 'Multiple du W/m² (10³). 1 kW/m² = "Full Sun" STC. Utilisé pour exprimer simplement la condition standard de test des modules PV.', NULL, '{"ISO 9488","IEC 60904-3:2019"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (62, 'mj_par_m2_jour', 'mégajoule par mètre carré par jour', 'MJ/m²/jour', 'irradiation_solaire', 'composee_mixte', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'mj_par_m2_jour', 'Unité de référence interne pour l''irradiation solaire dans Kuma (convention pragmatique alignée IEA/IRENA/NASA POWER). Représente l''énergie solaire totale reçue par mètre carré sur une journée moyenne. Valeurs typiques africaines : 18-25 MJ/m²/jour selon zone climatique.', NULL, '{"IEA Solar Heating and Cooling Programme","IRENA Country Profiles","NASA POWER (Prediction of Worldwide Energy Resources)","WMO Guide"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (84, 'metre_carre', 'mètre carré', 'm²', 'surface', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_carre', 'Unité SI dérivée cohérente sans nom spécial pour la surface (Tableau 5 BIPM). 1 m² = (1 m)².', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 5","ISO 80000-3"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (63, 'kwh_par_m2_jour', 'kilowattheure par mètre carré par jour', 'kWh/m²/jour', 'irradiation_solaire', 'composee_mixte', false, 3600000.000000000000000000000000000000, 0.000000000000000000000000000000, 'mj_par_m2_jour', 'Unité d''irradiation solaire journalière. 1 kWh/m²/jour = 3,6 MJ/m²/jour exactement. Largement utilisée dans les fiches techniques PV. Valeurs typiques africaines : 5-7 kWh/m²/jour (Sahel : 6,5 ; Sahara : 7+ ; côte ouest-africaine : 5-5,5).', NULL, '{"IRENA Country Profiles","NASA POWER","IEA PVPS"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (64, 'kwh_par_m2_an', 'kilowattheure par mètre carré par an', 'kWh/m²/an', 'irradiation_solaire', 'composee_mixte', false, 9856.564307527484000000000000000000, 0.000000000000000000000000000000, 'mj_par_m2_jour', 'Unité d''irradiation solaire annuelle. RECTIFICATION : utilisation de la convention IUPAC année grégorienne moyenne 365,2425 jours (et non 365 jours). 1 kWh/m²/an = 3 600 000 J/m² / (365,2425 × 86400 s/jour) en J/m²/jour, soit facteur 9856,564307527484 vers MJ/m²/jour. Valeurs typiques africaines : 1800-2500 kWh/m²/an (parmi les plus élevées du monde).', NULL, '{"IUPAC Green Book 1993","IRENA Country Profiles","PVGIS European Commission Joint Research Centre"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (65, 'volt', 'volt', 'V', 'tension_electrique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt', 'Unité SI dérivée avec nom spécial pour la tension électrique (Tableau 4 BIPM). 1 V = 1 W/A = kg·m²·s⁻³·A⁻¹. Nommée d''après Alessandro Volta.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (66, 'millivolt', 'millivolt', 'mV', 'tension_electrique', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'volt', 'Sous-multiple SI du volt. Utilisé pour les tensions de capteurs et thermocouples.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (67, 'kilovolt', 'kilovolt', 'kV', 'tension_electrique', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt', 'Multiple SI du volt. Standard pour les réseaux haute tension (HTA 20 kV, HTB 63-400 kV en France ; 11-33 kV distribution moyenne tension Afrique).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (68, 'megavolt', 'mégavolt', 'MV', 'tension_electrique', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt', 'Multiple SI du volt (10⁶). Utilisé pour les très hautes tensions (THT > 1 MV en HVDC, ex. ligne Cabora Bassa-Apollo Afrique du Sud à 533 kV).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (69, 'hertz', 'hertz', 'Hz', 'frequence', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'hertz', 'Unité SI dérivée avec nom spécial pour la fréquence (Tableau 4 BIPM). 1 Hz = 1 s⁻¹. Nommée d''après Heinrich Hertz. Standard mondial : 50 Hz (Europe, Afrique, Asie majeure) ou 60 Hz (Amériques, parties du Japon, Arabie saoudite).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (70, 'kilohertz', 'kilohertz', 'kHz', 'frequence', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'hertz', 'Multiple SI du hertz. Utilisé en électronique de puissance (commutation onduleurs PV).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (71, 'coulomb', 'coulomb', 'C', 'charge_electrique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'coulomb', 'Unité SI dérivée avec nom spécial pour la charge électrique (Tableau 4 BIPM). 1 C = 1 A·s. Charge élémentaire e = 1,602176634 × 10⁻¹⁹ C exactement (depuis SI 2019).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (72, 'ampereheure', 'ampèreheure', 'Ah', 'charge_electrique', 'composee_mixte', false, 3600.000000000000000000000000000000, 0.000000000000000000000000000000, 'coulomb', 'Charge composée combinant ampère (SI) et heure (non-SI acceptée). 1 Ah = 1 A × 3600 s = 3600 C exactement. ALIAS SÉMANTIQUE : couvre capacite_stockage_electrique (capacité des batteries) qui est la même grandeur physique. Standard pour les capacités batteries (résidentielles 50-200 Ah, véhicules électriques 20-100 kAh).', NULL, '{"IEC 60050","IEC 61960 (lithium-ion)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (73, 'milliampereheure', 'milliampèreheure', 'mAh', 'charge_electrique', 'composee_mixte', false, 3.600000000000000000000000000000, 0.000000000000000000000000000000, 'coulomb', 'Sous-multiple de l''Ah. Standard pour les batteries de petits appareils (smartphones 3000-5000 mAh).', NULL, '{"IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (74, 'kiloampereheure', 'kiloampèreheure', 'kAh', 'charge_electrique', 'composee_mixte', false, 3600000.000000000000000000000000000000, 0.000000000000000000000000000000, 'coulomb', 'Multiple de l''Ah (10³). Utilisé pour les batteries de véhicules électriques et stockage stationnaire.', NULL, '{"IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (75, 'ohm', 'ohm', 'Ω', 'resistance_electrique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'ohm', 'Unité SI dérivée avec nom spécial pour la résistance électrique (Tableau 4 BIPM). 1 Ω = 1 V/A = kg·m²·s⁻³·A⁻². Nommée d''après Georg Ohm. Constante de von Klitzing R_K = 25 812,807459 3045 Ω exactement (SI 2019).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (76, 'kiloohm', 'kiloohm', 'kΩ', 'resistance_electrique', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'ohm', 'Multiple SI de l''ohm. Utilisé en électronique.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (77, 'megaohm', 'mégaohm', 'MΩ', 'resistance_electrique', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'ohm', 'Multiple SI de l''ohm (10⁶). Utilisé pour mesurer la résistance d''isolement (essais de diélectrique).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (78, 'volt_ampere', 'volt-ampère', 'VA', 'puissance_apparente', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt_ampere', 'Unité de puissance apparente, dimensionnellement équivalente au watt mais sémantiquement distincte. La puissance apparente est S = U×I (en valeurs efficaces). Pour systèmes purement résistifs : 1 VA = 1 W. Pour systèmes inductifs/capacitifs : VA > W. Utilisée pour dimensionner les transformateurs, onduleurs, alternateurs.', NULL, '{"IEC 60050","IEC 60076 (transformateurs)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (79, 'kilovolt_ampere', 'kilovolt-ampère', 'kVA', 'puissance_apparente', 'composee_mixte', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt_ampere', 'Multiple SI du volt-ampère. Standard pour les transformateurs de distribution (typiquement 50-1000 kVA).', NULL, '{"IEC 60050","IEC 60076"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (80, 'megavolt_ampere', 'mégavolt-ampère', 'MVA', 'puissance_apparente', 'composee_mixte', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'volt_ampere', 'Multiple SI du volt-ampère (10⁶). Standard pour les transformateurs de transport (typiquement 50-500 MVA).', NULL, '{"IEC 60050","IEC 60076"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (81, 'var', 'volt-ampère réactif', 'var', 'puissance_reactive', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'var', 'Unité de puissance réactive. Symbole en MINUSCULES "var" selon convention IEC Stockholm 1930 (pour éviter confusion avec le préfixe Var). Représente la puissance échangée entre source et charges réactives sans dissipation. Q = U×I×sin(φ).', NULL, '{"IEC 60050","IEC Stockholm 1930"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (82, 'kilovar', 'kilovolt-ampère réactif', 'kvar', 'puissance_reactive', 'composee_mixte', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'var', 'Multiple du var. Symbole "kvar" avec k minuscule (ne pas écrire "kVAR").', NULL, '{"IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (83, 'megavar', 'mégavolt-ampère réactif', 'Mvar', 'puissance_reactive', 'composee_mixte', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'var', 'Multiple du var (10⁶). Symbole "Mvar" avec M majuscule (préfixe SI méga). Utilisé pour les compensateurs de puissance réactive industriels.', NULL, '{"IEC 60050"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (85, 'kilometre_carre', 'kilomètre carré', 'km²', 'surface', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_carre', 'Multiple SI du m². 1 km² = 10⁶ m². Utilisé pour les surfaces administratives, bassins versants.', NULL, '{"BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (86, 'hectare', 'hectare', 'ha', 'surface', 'non_SI_acceptee', false, 10000.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_carre', 'Unité non-SI acceptée pour usage avec le SI selon le Tableau 8 de la brochure BIPM. Définie comme exactement 10⁴ m² (carré de 100 m × 100 m). CRITIQUE pour les projets PV utility-scale africains : Noor Ouarzazate 3000 ha, Benban Égypte 3700 ha, Bokhol Sénégal 75 ha. Densité PV typique : 0,4-0,5 ha/MWc.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8","IRENA Renewable Capacity Statistics"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (87, 'metre_cube', 'mètre cube', 'm³', 'volume', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_cube', 'Unité SI dérivée cohérente sans nom spécial pour le volume (Tableau 5 BIPM). 1 m³ = (1 m)³. Pour gaz naturel : utiliser conditions standard (Sm³ ou Nm³ : 0°C, 1 atm).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 5","ISO 80000-3"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (88, 'litre', 'litre', 'L', 'volume', 'non_SI_acceptee', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'metre_cube', 'Unité non-SI acceptée pour usage avec le SI selon Tableau 8 BIPM. Définie comme exactement 10⁻³ m³ = 1 dm³. Symbole majuscule "L" préféré au minuscule "l" pour éviter confusion avec chiffre 1.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (89, 'millilitre', 'millilitre', 'mL', 'volume', 'non_SI_acceptee', false, 0.000001000000000000000000000000, 0.000000000000000000000000000000, 'metre_cube', 'Sous-multiple du litre. 1 mL = 10⁻³ L = 10⁻⁶ m³.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (90, 'barril_petrole', 'baril de pétrole', 'bbl', 'volume', 'imperial', false, 0.158987294928000000000000000000, 0.000000000000000000000000000000, 'metre_cube', 'Unité de volume du système impérial américain, devenue STANDARD UNIVERSEL du marché pétrolier mondial. Définie comme exactement 42 US gallons = 158,987294928 L (le US gallon valant exactement 3,785411784 L par accord international 1959). Utilisée par OPEP, AIE, EIA pour la production pétrolière. Origine 1866 Pennsylvanie. Note industrielle : un "baril standard" est défini à 60°F et 1 atm.', NULL, '{"API Manual of Petroleum Measurement Standards","NIST SP 811","AIE/IEA World Energy Statistics","OPEC Annual Statistical Bulletin","ISO 91","Accord international 1959"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (91, 'metre_cube_par_seconde', 'mètre cube par seconde', 'm³/s', 'debit_volumique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_cube_par_seconde', 'Unité SI dérivée pour le débit volumique. Utilisée pour les analyses scientifiques hydroélectriques. Exemples africains : Cahora Bassa Mozambique 3000 m³/s, Akosombo Ghana 1000 m³/s, fleuve Congo à Boyoma 40 000 m³/s.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-4","IEC 60041"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (92, 'metre_cube_par_heure', 'mètre cube par heure', 'm³/h', 'debit_volumique', 'composee_mixte', false, 0.000277777777777778000000000000, 0.000000000000000000000000000000, 'metre_cube_par_seconde', 'Unité composée combinant m³ (SI) et heure (non-SI acceptée). 1 m³/h = 1/3600 m³/s. Forme la plus utilisée dans les fiches techniques d''équipements (pompes, ventilateurs, compteurs gaz).', NULL, '{"BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (93, 'litre_par_seconde', 'litre par seconde', 'L/s', 'debit_volumique', 'composee_mixte', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'metre_cube_par_seconde', 'Unité composée pour les petits débits domestiques. 1 L/s = 0,001 m³/s = 3,6 m³/h. Pompes solaires résidentielles typiques : 0,5-2 L/s.', NULL, '{"BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (94, 'litre_par_minute', 'litre par minute', 'L/min', 'debit_volumique', 'composee_mixte', false, 0.000016666666666666700000000000, 0.000000000000000000000000000000, 'metre_cube_par_seconde', 'Unité de plomberie domestique et petit pompage. 1 L/min = 1/60 L/s = 1,667 × 10⁻⁵ m³/s.', NULL, '{"BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (95, 'kilogramme_par_metre_cube', 'kilogramme par mètre cube', 'kg/m³', 'densite_massique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_par_metre_cube', 'Unité SI dérivée pour la masse volumique (Tableau 5 BIPM). DISTINCTION TERMINOLOGIQUE : "masse volumique" (grandeur dimensionnée en kg/m³) ≠ "densité relative" (sans dimension, ratio à l''eau). Référence : eau à 4°C = 1000 kg/m³ exactement (par construction historique du gramme).', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 5","ISO 80000-4","IUPAC Green Book"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (96, 'gramme_par_litre', 'gramme par litre', 'g/L', 'densite_massique', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_par_metre_cube', 'Unité numériquement IDENTIQUE au kg/m³ : 1 g/L = 1 kg/m³ exactement (les préfixes décimaux du gramme et du litre se compensent). Très utilisée en chimie et analyse de l''eau.', NULL, '{"BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (97, 'gramme_par_centimetre_cube', 'gramme par centimètre cube', 'g/cm³', 'densite_massique', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_par_metre_cube', 'Unité utilisée en physique des matériaux. Référence intuitive : eau pure à 4°C = exactement 1 g/cm³. Exemples : silicium PV 2,33 g/cm³, aluminium 2,70 g/cm³, cuivre 8,96 g/cm³, plomb (batteries) 11,34 g/cm³.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (98, 'kilogramme_par_metre_cube_air', 'kilogramme par mètre cube (air)', 'kg/m³', 'densite_air', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_par_metre_cube_air', 'Cas particulier de masse volumique appliqué à l''air, sémantiquement DISTINCT de densite_massique parce que la densité de l''air est une grandeur d''ÉTAT dépendant du contexte (température, pression, humidité), alors que la densité d''un combustible est une propriété INTRINSÈQUE. Référence ISA : 1,225 kg/m³ à 15°C, 1 atm, niveau mer. CRITIQUE pour l''éolien : P = ½×ρ×A×v³ donc ±5% sur ρ → ±5% sur P. Sites en altitude (Atlas, Éthiopie, Lesotho) : densité réduite de 10-25%.', NULL, '{"ISO 2533 (Standard Atmosphere)","IEC 61400-12 (Wind turbines)","ICAO Doc 7488","BIPM SI Brochure 9ème édition (2019)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (99, 'metre_par_seconde', 'mètre par seconde', 'm/s', 'vitesse', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'metre_par_seconde', 'Unité SI dérivée pour la vitesse. Référence scientifique pour les analyses éoliennes. Classifications IEC 61400 : <4 m/s faible, 4-6 modéré, 6-8 bon, 8-10 très bon, >10 exceptionnel (ex. Lake Turkana Kenya 11 m/s).', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-3","IEC 61400"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (100, 'kilometre_par_heure', 'kilomètre par heure', 'km/h', 'vitesse', 'composee_mixte', false, 0.277777777777778000000000000000, 0.000000000000000000000000000000, 'metre_par_seconde', 'Unité composée combinant km (SI) et h (non-SI acceptée). 1 km/h = 1/3,6 m/s ≈ 0,2778 m/s. Très utilisée en météorologie civile et bulletins quotidiens.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","WMO Guide"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (118, 'kilojoule_par_kilogramme', 'kilojoule par kilogramme', 'kJ/kg', 'pouvoir_calorifique', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule_par_kilogramme', 'Multiple SI lisible pour les valeurs de pouvoir calorifique (bois sec 16 000-18 000 kJ/kg PCI).', NULL, '{"ISO 1928","ISO 18125"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (101, 'noeud', 'nœud', 'kn', 'vitesse', 'non_SI_acceptee', false, 0.514444444444445000000000000000, 0.000000000000000000000000000000, 'metre_par_seconde', 'Unité non-SI acceptée par BIPM pour la marine, l''aviation et la météorologie. Définie comme 1 mille marin par heure : 1 nœud = 1852 m / 3600 s = 0,5144 m/s exactement (mille marin international = 1852 m, ITHC 1929). Symbole "kn" préféré ISO/IEEE/IHO. Utilisée pour les vents côtiers africains et l''éolien offshore.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 8","ISO 80000-3","IHO Hydrographic Dictionary","ICAO Doc 7488","ITHC 1929"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (102, 'pascal', 'pascal', 'Pa', 'pression', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'pascal', 'Unité SI dérivée avec nom spécial pour la pression (Tableau 4 BIPM). 1 Pa = 1 N/m² = kg·m⁻¹·s⁻². Adoptée 14ème CGPM 1971. Nommée d''après Blaise Pascal.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 4","14ème CGPM (1971)","ISO 80000-4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (103, 'kilopascal', 'kilopascal', 'kPa', 'pression', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'pascal', 'Multiple SI du pascal. Pression atmosphérique standard 101,3 kPa.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (104, 'megapascal', 'mégapascal', 'MPa', 'pression', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'pascal', 'Multiple SI du pascal (10⁶). Pression vapeur centrales thermiques 10-25 MPa, gaz transport HP 7-8 MPa.', NULL, '{"BIPM SI Brochure 9ème édition (2019), Tableau 7"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (105, 'bar', 'bar', 'bar', 'pression', 'non_SI_acceptee', false, 100000.000000000000000000000000000000, 0.000000000000000000000000000000, 'pascal', 'Unité de pression non-SI tolérée par BIPM. Définie comme exactement 100 000 Pa = 10⁵ Pa. 1 bar ≈ 1 atm (différence < 1,3%). Très utilisée en industrie (compresseurs 7-10 bar, pneumatiques 2-3 bar).', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-4","DIN 1314"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (106, 'atmosphere', 'atmosphère standard', 'atm', 'pression', 'non_SI_acceptee', false, 101325.000000000000000000000000000000, 0.000000000000000000000000000000, 'pascal', 'Atmosphère standard définie comme exactement 101 325 Pa par 10ème CGPM 1954. Représente la pression atmosphérique moyenne au niveau mer. Standard pour conditions normalisées (STC PV, équations gaz). Distincte de l''atmosphère technique (at = 98 066,5 Pa).', NULL, '{"10ème CGPM (1954), résolution 4","BIPM SI Brochure 9ème édition (2019)","ISO 80000-4"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (107, 'gramme_co2', 'gramme de CO2', 'gCO2', 'masse_co2', 'SI', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_co2', 'Unité de masse de CO2 sémantiquement DISTINCTE de la masse générale (gramme) pour permettre le suivi spécifique des émissions carbone. DISTINCTION CRITIQUE : CO2 vs CO2eq (équivalent CO2 incluant CH4, N2O, etc. via leur PRG). Cette unité concerne uniquement le CO2.', NULL, '{"ISO 14064-1:2018","GHG Protocol Corporate Standard"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (108, 'kilogramme_co2', 'kilogramme de CO2', 'kgCO2', 'masse_co2', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_co2', 'Unité de référence interne pour la masse de CO2 (cohérente avec la grandeur masse). Standard pour les bilans GES individuels et résidentiels.', NULL, '{"ISO 14064-1:2018","GHG Protocol"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (109, 'tonne_co2', 'tonne de CO2', 'tCO2', 'masse_co2', 'SI', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_co2', 'Multiple critique pour les bilans GES nationaux et corporatifs. Une voiture moyenne émet 2 tCO2/an, une maison 3 tCO2/an, une centrale charbon 7 MtCO2/an.', NULL, '{"ISO 14064-1:2018","GHG Protocol","IPCC AR6"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (110, 'megatonne_co2', 'mégatonne de CO2', 'MtCO2', 'masse_co2', 'SI', false, 1000000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_co2', 'Multiple pour les bilans nationaux et continentaux. Émissions mondiales annuelles : 37 GtCO2 = 37 000 MtCO2.', NULL, '{"ISO 14064-1:2018","IPCC AR6","IEA Global Energy Review"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (111, 'gco2_par_kwh', 'gramme de CO2 par kilowattheure', 'gCO2/kWh', 'intensite_carbone', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gco2_par_kwh', 'Unité de RÉFÉRENCE INTERNE Kuma pour intensité carbone (convention pragmatique). Standard international utilisé par GIEC, AIE, IRENA. Le SI strict serait kg/J (= 2,78×10⁻¹⁰), peu lisible. Cohérence avec standards : 1 gCO2/kWh = 1 kgCO2/MWh = 1 tCO2/GWh. Médianes IPCC AR6 par filière : charbon 820, gaz 490, pétrole 733, PV 41-48, éolien 11, hydro 24, nucléaire 12 gCO2/kWh.', NULL, '{"IPCC AR5 WG3 Annex III","IPCC AR6 WG3 Chapter 6 (2022)","IEA Methodology for CO₂ Emissions","ISO 14064-1:2018","UNECE LCA Electricity 2022"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (112, 'kgco2_par_mwh', 'kilogramme de CO2 par mégawattheure', 'kgCO2/MWh', 'intensite_carbone', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gco2_par_kwh', 'Unité numériquement IDENTIQUE à gCO2/kWh (1:1 par construction métrologique). Utilisée dans certains rapports nationaux.', NULL, '{"IPCC AR6"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (113, 'tco2_par_mwh', 'tonne de CO2 par mégawattheure', 'tCO2/MWh', 'intensite_carbone', 'composee_mixte', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'gco2_par_kwh', 'Multiple utilisé pour analyses macro et projets utility-scale. 1 tCO2/MWh = 1000 gCO2/kWh. Centrales charbon 0,82 tCO2/MWh.', NULL, '{"IPCC AR6",IEA}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (114, 'tco2_par_gwh', 'tonne de CO2 par gigawattheure', 'tCO2/GWh', 'intensite_carbone', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gco2_par_kwh', 'Unité numériquement IDENTIQUE à gCO2/kWh (1:1). Utilisée dans les inventaires nationaux GES (Communications Nationales CCNUCC).', NULL, '{"IPCC AR6","CCNUCC National GHG Inventories"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (115, 'tco2_par_habitant_an', 'tonne de CO2 par habitant et par an', 'tCO2/hab/an', 'empreinte_carbone_habitant', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'tco2_par_habitant_an', 'Unité STANDARD INTERNATIONALE pour l''empreinte carbone individuelle (GIEC, AIE, CCNUCC, Banque Mondiale). La grandeur n''a pas d''équivalent SI strict (la "personne" n''est pas une unité métrologique BIPM) - convention pragmatique alignée standards climat. Distinction CO2 vs CO2eq comme pour intensite_carbone. Inégalité critique : Tchad/Niger 0,1 tCO2/hab/an vs USA 14,4 (rapport 1:144). Guinée 0,3 tCO2/hab/an. Moyenne mondiale 4,7 tCO2/hab/an.', NULL, '{"IPCC AR6 WG3 SPM (2022)","IPCC AR5 WG3","CCNUCC National GHG Inventories","IEA GHG Emissions from Energy","Global Carbon Project (Annual Budget)","ISO 14064-1:2018","EDGAR (JRC/IEA)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (116, 'kgco2_par_habitant_an', 'kilogramme de CO2 par habitant et par an', 'kgCO2/hab/an', 'empreinte_carbone_habitant', 'composee_mixte', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'tco2_par_habitant_an', 'Sous-multiple utile pour les pays à très faible empreinte (Tchad, Niger 100 kgCO2/hab/an) où l''expression en tCO2 (0,1) devient peu lisible.', NULL, '{"IPCC AR6","Global Carbon Project"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (117, 'joule_par_kilogramme', 'joule par kilogramme', 'J/kg', 'pouvoir_calorifique', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule_par_kilogramme', 'Unité SI dérivée pour le pouvoir calorifique massique. CONVENTION CRITIQUE Kuma : valeurs PAR DÉFAUT en PCI (Pouvoir Calorifique Inférieur, LHV) selon convention internationale (AIE, IRENA, Europe). Pour sources publiant en PCS (HHV, convention nord-américaine), une note explicite est ajoutée. Différence PCS-PCI : 5-15% selon le combustible.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 1928 (combustibles minéraux solides)","ISO 18125 (biocombustibles solides)","ISO 6976 (gaz naturel)","IEA Energy Statistics Manual"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (119, 'megajoule_par_kilogramme', 'mégajoule par kilogramme', 'MJ/kg', 'pouvoir_calorifique', 'SI', false, 1000000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule_par_kilogramme', 'STANDARD INTERNATIONAL des rapports IEA, IRENA, FAO. Valeurs PCI typiques : bois sec 18, charbon de bois 30, charbon minéral 25-30, diesel 42,8, méthane pur 50, bioéthanol 26,8, biodiesel 37 MJ/kg. CRITIQUE pour la biomasse africaine (déchets agricoles, balles de riz, coques d''arachide).', NULL, '{"IEA Energy Statistics Manual",IRENA,"FAO Forestry Statistics","ISO 1928","ISO 18125"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (120, 'kilowattheure_par_kilogramme', 'kilowattheure par kilogramme', 'kWh/kg', 'pouvoir_calorifique', 'composee_mixte', false, 3600000.000000000000000000000000000000, 0.000000000000000000000000000000, 'joule_par_kilogramme', 'Unité utilisée pour les BATTERIES (densité énergétique massique stockable, distincte du pouvoir calorifique de combustion mais même unité). 1 kWh/kg = 3,6 MJ/kg. Plomb-acide 30-50 Wh/kg, Li-ion LiFePO4 90-120 Wh/kg, Li-ion NMC 150-250 Wh/kg.', NULL, '{"IEC 61960 (lithium-ion)","ISO 1928"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (121, 'kilocalorie_par_kilogramme', 'kilocalorie par kilogramme', 'kcal/kg', 'pouvoir_calorifique', 'autre', false, 4186.800000000000000000000000000000, 0.000000000000000000000000000000, 'joule_par_kilogramme', 'Unité historique (calorie internationale IT). 1 kcal/kg = 4 186,8 J/kg = 4,1868 kJ/kg. Utilisée dans rapports FAO et anciens documents énergétiques africains.', NULL, '{"ISO 1928","5th International Conference on Properties of Steam, London 1956",FAO}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (122, 'sans_unite', 'sans unité', '1', 'sans_dimension', 'SI', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'sans_unite', 'Unité "neutre" pour grandeurs sans dimension. Utilisée pour le facteur de puissance (cos φ), les rapports, les indices, les efficacités fractionnaires. Symbole "1" selon BIPM (ou pas de symbole). ALIAS SÉMANTIQUE : couvre facteur_puissance, rendement_fractionnaire, ratios divers.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-1"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (123, 'pourcent', 'pourcent', '%', 'sans_dimension', 'non_SI_acceptee', false, 0.010000000000000000000000000000, 0.000000000000000000000000000000, 'sans_unite', 'Convention multiplicative : 1% = 0,01 (sans dimension). Utilisée pour rendements, facteurs de capacité, taux de pertes, intermittence des renouvelables. Exemples PV : facteur de capacité 15-25%, rendement modules 18-22%, pertes onduleur 2-5%.', NULL, '{"BIPM SI Brochure 9ème édition (2019)","ISO 80000-1"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (124, 'gnf_par_kwh', 'franc guinéen par kilowattheure', 'GNF/kWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gnf_par_kwh', 'Unité de coût unitaire de l''énergie en francs guinéens. Code ISO 4217 : GNF. Émetteur : Banque Centrale de la République de Guinée (BCRG). Particularité : la Guinée a opté pour une monnaie INDÉPENDANTE avec taux de change FLOTTANT depuis 1960 (refus de la zone franc CFA après l''indépendance), contrairement aux pays voisins UEMOA. Taux indicatifs 2024-2025 : 1 USD ≈ 8500-8700 GNF, 1 EUR ≈ 9200-9400 GNF. CONVENTION KUMA STRATÉGIE B : devise pivot GNF, pas de conversion automatique vers USD/EUR/XOF. PERTINENCE CRITIQUE : pays de LANCEMENT de Kuma Science. Tarifs résidentiels Conakry typiques 2024 : tarif social 500-700 GNF/kWh, tarif normal 900-1200 GNF/kWh (EDG - Électricité De Guinée). ALIAS SÉMANTIQUES : couvre cout_actualise_energie (LCOE), tarif_soutirage, tarif_rachat. La distinction se fait au niveau de la mesure via un champ "convention" à ajouter ultérieurement.', NULL, '{"ISO 4217 (Codes des devises) : GNF","Banque Centrale de la République de Guinée (BCRG)","Loi n°60/01 du 1er mars 1960 (création franc guinéen)"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (125, 'gnf_par_mwh', 'franc guinéen par mégawattheure', 'GNF/MWh', 'cout_unitaire_energie', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'gnf_par_kwh', 'Multiple échelle MWh pour analyses macro Guinée. 1 GNF/MWh = 0,001 GNF/kWh.', NULL, '{BCRG}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (126, 'xof_par_kwh', 'franc CFA UEMOA par kilowattheure', 'XOF/kWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'xof_par_kwh', 'Devise officielle des 8 pays UEMOA (Bénin, Burkina Faso, Côte d''Ivoire, Guinée-Bissau, Mali, Niger, Sénégal, Togo). Code ISO 4217 : XOF. Émetteur : BCEAO (Banque Centrale des États de l''Afrique de l''Ouest). PARITÉ FIXE avec euro depuis 1999 : 1 EUR = 655,957 XOF exactement (garantie Trésor français). CONVENTION KUMA STRATÉGIE B : devise pivot XOF, pas de conversion automatique. Exemples 2024 : tarif BT Sénégal 110 XOF/kWh, Côte d''Ivoire 85 XOF/kWh, Mali 115 XOF/kWh.', NULL, '{"ISO 4217 : XOF",BCEAO,"Traité UEMOA 1994"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (127, 'xof_par_mwh', 'franc CFA UEMOA par mégawattheure', 'XOF/MWh', 'cout_unitaire_energie', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'xof_par_kwh', 'Multiple échelle MWh pour analyses macro UEMOA.', NULL, '{BCEAO}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (128, 'xaf_par_kwh', 'franc CFA CEMAC par kilowattheure', 'XAF/kWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'xaf_par_kwh', 'Devise officielle des 6 pays CEMAC (Cameroun, RCA, Tchad, Congo, Guinée Équatoriale, Gabon). Code ISO 4217 : XAF. Émetteur : BEAC (Banque des États de l''Afrique Centrale, Yaoundé). PARITÉ FIXE avec euro : 1 EUR = 655,957 XAF (identique à XOF). DISTINCTION CRITIQUE : XAF et XOF ont la même valeur faciale mais NE SONT PAS interchangeables physiquement (deux banques centrales distinctes). Exemples 2024 : tarif BT Cameroun 85 XAF/kWh (ENEO), Gabon 110 XAF/kWh (SEEG).', NULL, '{"ISO 4217 : XAF",BEAC,"Traité CEMAC 1994"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (129, 'xaf_par_mwh', 'franc CFA CEMAC par mégawattheure', 'XAF/MWh', 'cout_unitaire_energie', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'xaf_par_kwh', 'Multiple échelle MWh pour analyses macro CEMAC.', NULL, '{BEAC}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (130, 'mad_par_kwh', 'dirham marocain par kilowattheure', 'MAD/kWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'mad_par_kwh', 'Devise officielle du Maroc. Code ISO 4217 : MAD. Émetteur : Bank Al-Maghrib (BAM, Rabat). Régime de change SEMI-FLOTTANT depuis janvier 2018 : adossé à panier euro 60% + USD 40%, fluctuation autorisée ±5%. Taux 2024-2025 : 1 USD ≈ 9,8-10,2 MAD, 1 EUR ≈ 10,7-11,1 MAD. PERTINENCE : Maroc = leader africain transition énergétique (Noor, Tarfaya, Midelt). Tarif BT (ONEE) : 0,90-1,40 MAD/kWh selon tranches. LCOE PV utility-scale appels d''offres MASEN : 0,30-0,40 MAD/kWh.', NULL, '{"ISO 4217 : MAD","Bank Al-Maghrib (BAM)","Réforme régime de change janvier 2018"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (131, 'mad_par_mwh', 'dirham marocain par mégawattheure', 'MAD/MWh', 'cout_unitaire_energie', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'mad_par_kwh', 'Multiple échelle MWh pour analyses macro Maroc.', NULL, '{BAM}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (132, 'eur_par_mwh', 'euro par mégawattheure', 'EUR/MWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'eur_par_mwh', 'Devise pivot EUR (échelle MWh comme standard européen). Code ISO 4217 : EUR. Émetteur : Banque Centrale Européenne. Standard européen utilisé par bourses énergétiques (EPEX SPOT, Nord Pool), rapports ENTSO-E, Agence européenne pour l''environnement. Prix marché spot européen typique 2024-2025 : 50-100 EUR/MWh.', NULL, '{"ISO 4217 : EUR",BCE,"EPEX SPOT",ENTSO-E}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (133, 'eur_par_kwh', 'euro par kilowattheure', 'EUR/kWh', 'cout_unitaire_energie', 'autre', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'eur_par_mwh', 'Échelle kWh pour tarifs résidentiels européens. 1 EUR/kWh = 1000 EUR/MWh.', NULL, '{"ISO 4217 : EUR"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (134, 'usd_par_mwh', 'dollar US par mégawattheure', 'USD/MWh', 'cout_unitaire_energie', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'usd_par_mwh', 'Devise pivot USD (échelle MWh comme standard international). Code ISO 4217 : USD. Standard international utilisé par AIE (IEA), IRENA, Banque Mondiale, rapports marchés énergétiques. Pertinence Kuma : LCOE solaire utility-scale africain 30-50 USD/MWh, contrats PPA, comparaisons internationales.', NULL, '{"ISO 4217 : USD","IEA Methodology for LCOE","IRENA Renewable Power Generation Costs","World Bank ESMAP"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (135, 'usd_par_kwh', 'dollar US par kilowattheure', 'USD/kWh', 'cout_unitaire_energie', 'autre', false, 1000.000000000000000000000000000000, 0.000000000000000000000000000000, 'usd_par_mwh', 'Échelle kWh pour tarifs résidentiels et internationaux. 1 USD/kWh = 1000 USD/MWh.', NULL, '{"ISO 4217 : USD"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (136, 'gnf_par_kw', 'franc guinéen par kilowatt', 'GNF/kW', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gnf_par_kw', 'CAPEX par capacité électrique installée en GNF/kW. Famille A (par puissance électrique nominale, distincte de la Famille B par Wc PV). Pertinence Kuma : analyses CAPEX projets énergétiques guinéens. Souapiti hydroélectrique 450 MW estimé 2800 USD/kW = 24 millions GNF/kW aux taux 2024.', NULL, '{"IRENA Renewable Power Generation Costs",BCRG}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (137, 'xof_par_kw', 'franc CFA UEMOA par kilowatt', 'XOF/kW', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'xof_par_kw', 'CAPEX en XOF/kW. Famille A. Devise pivot XOF.', NULL, '{IRENA,BCEAO}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
