INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (139, 'mad_par_kw', 'dirham marocain par kilowatt', 'MAD/kW', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'mad_par_kw', 'CAPEX en MAD/kW. Famille A. Devise pivot MAD. Pertinence Maroc : projets MASEN, Noor CSP.', NULL, '{IRENA,BAM}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (140, 'eur_par_kw', 'euro par kilowatt', 'EUR/kW', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'eur_par_kw', 'CAPEX en EUR/kW. Famille A. Devise pivot EUR. Standard européen pour financement (BEI, AFD, KfW).', NULL, '{IRENA,BCE}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (141, 'usd_par_kw', 'dollar US par kilowatt', 'USD/kW', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'usd_par_kw', 'CAPEX par puissance électrique en USD/kW. STANDARD INTERNATIONAL IRENA/IEA/World Bank pour CAPEX projets énergétiques. Famille A : centrales thermiques, hydro, éolien, géothermie, CSP. Distinction critique avec USD/Wc (Famille B PV) : 1 Wc PV ≠ 1 W thermique en énergie produite (facteur de capacité différent). Exemples 2024-2025 : charbon 1500-2500, CCGT 800-1200, hydro grand 1500-3500, éolien terrestre 1200-1800, éolien offshore 2800-4200, géothermique 2500-5000, nucléaire 4500-12000 USD/kW.', NULL, '{"IRENA Renewable Power Generation Costs (annuel)","IEA World Energy Investment","World Bank ESMAP"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (142, 'gnf_par_wc', 'franc guinéen par watt-crête', 'GNF/Wc', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'gnf_par_wc', 'CAPEX PV en GNF/Wc. Famille B (puissance crête PV STC). Pertinence Kuma : analyses CAPEX projets PV guinéens (futurs développements PV utility-scale et hors-réseau).', NULL, '{IRENA,BCRG,"IEC 61215-1:2021"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
