INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (151, 'eur_par_kwc', 'euro par kilowatt-crête', 'EUR/kWc', 'cout_investissement_capacite', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'eur_par_wc', 'Multiple échelle kWc pour CAPEX PV utility-scale européens et africains.', NULL, '{IRENA,BCE}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (152, 'usd_par_wc', 'dollar US par watt-crête', 'USD/Wc', 'cout_investissement_capacite', 'autre', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'usd_par_wc', 'CAPEX par capacité PV en USD/Wc. STANDARD INTERNATIONAL pour PV (IRENA, IEA, NREL, BloombergNEF). Famille B : EXCLUSIVEMENT pour photovoltaïque, dénominateur Wc en conditions STC (1000 W/m², 25°C, AM1.5). Distinction critique avec USD/kW (Famille A) : facteurs de capacité différents (PV 15-25% vs thermique 70-90%). 1 USD/Wc = 1000 USD/kWc = 1 000 000 USD/MWc. Échelle USD/Wc privilégiée pour résidentiel/commercial (1-2 USD/Wc), USD/kWc pour utility-scale (600-900 USD/kWc). Exemples 2024 : Benban Égypte 0,80 USD/Wc, Noor PV Maroc 0,90 USD/Wc, Bokhol Sénégal 1,30 USD/Wc, résidentiel africain 1,50-2,00 USD/Wc.', NULL, '{"IRENA Renewable Power Generation Costs","IEA Renewables","NREL Solar PV System Cost Benchmark",BloombergNEF,"IEC 61215-1:2021","IEC 60904-3:2019"}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (153, 'usd_par_kwc', 'dollar US par kilowatt-crête', 'USD/kWc', 'cout_investissement_capacite', 'autre', false, 0.001000000000000000000000000000, 0.000000000000000000000000000000, 'usd_par_wc', 'Multiple échelle kWc pour CAPEX PV utility-scale internationaux. 1 USD/kWc = 0,001 USD/Wc. Valeurs typiques utility-scale 600-900 USD/kWc.', NULL, '{IRENA,IEA,NREL}', true, NULL, '2026-09-17 06:04:12.391117+00', NULL, '2026-09-17 06:04:12.391117+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (154, 'kwh_par_kwc_jour', 'kilowattheure par kilowatt-crête par jour', 'kWh/kWc/jour', 'productible_specifique_quotidien', 'composee_mixte', false, 0.041666666666666666666666666667, 0.000000000000000000000000000000, 'sans_unite', 'Productible spécifique journalier d''un système photovoltaïque. Énergie produite par kilowatt-crête installé sur une journée. Standard IEC 61724-1, IEA PVPS Task 13. Cadence éditoriale Kuma pour le productible journalier.', NULL, '{"IEC 61724-1 (Photovoltaic system performance - Part 1 : Monitoring)","IEA PVPS Task 13","IRENA Country Profiles"}', true, NULL, '2026-09-17 06:04:12.515666+00', NULL, '2026-09-17 06:04:12.515666+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (155, 'kwh_par_kwc_mois', 'kilowattheure par kilowatt-crête par mois', 'kWh/kWc/mois', 'productible_specifique_mensuel', 'composee_mixte', false, 0.001368953503494253817669082870, 0.000000000000000000000000000000, 'sans_unite', 'Productible spécifique mensuel d''un système photovoltaïque. Cumul mensuel de l''énergie produite par kilowatt-crête installé. Utilisé pour caractériser la saisonnalité énergétique d''un site.', NULL, '{"IEC 61724-1 (Photovoltaic system performance - Part 1 : Monitoring)","IEA PVPS Task 13","IRENA Country Profiles"}', true, NULL, '2026-09-17 06:04:12.515666+00', NULL, '2026-09-17 06:04:12.515666+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (156, 'heure_equivalente_pleine', 'heure équivalente pleine', 'HEP', 'productivite_solaire', 'composee_mixte', false, 3600.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Convention internationale Equivalent Full Load Hours (EFLH). Quotient de l''énergie produite par la puissance crête nominale, exprimé en heures équivalentes. Distincte sémantiquement de l''unité "heure" bien que dimensionnellement identique (facteur SI = 3600). Standard pour caractériser la productivité d''un site PV.', NULL, '{"IEC 61724-1 (Photovoltaic system performance - Part 1 : Monitoring)","IEA PVPS Task 13","IRENA Country Profiles"}', true, NULL, '2026-09-17 06:04:12.515666+00', NULL, '2026-09-17 06:04:12.515666+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (157, 'degre_jour', 'degré-jour', '°C·jour', 'duree_temperature', 'composee_mixte', false, 1.000000000000000000000000000000, 0.000000000000000000000000000000, 'degre_jour', 'Cumul des écarts entre une température de référence (base) et la température journalière moyenne. Unité de base pour les calculs de besoins thermiques de chauffage ou de climatisation. Dimension SI exacte : kelvin × seconde (différentiel de température cumulé sur durée). Code unite_si autoréférent dans Kuma, faute d''unité SI scalaire directe.', NULL, '{"ISO 15927-6 (Hygrothermal performance of buildings - Calculation and presentation of climatic data - Part 6 : Accumulated temperature differences (degree-days))","ASHRAE Fundamentals Handbook (Climatic Design Information)"}', true, NULL, '2026-09-17 06:04:12.515666+00', NULL, '2026-09-17 06:04:12.515666+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (158, 'mm_par_jour', 'millimetre par jour', 'mm/jour', 'precipitation', 'composee_mixte', false, 0.000000011574074074074074074074, 0.000000000000000000000000000000, 'metre_par_seconde', 'Hauteur de precipitation cumulee sur une journee. Convention meteorologique standard (lame d''eau en millimetres equivalente a des litres par metre carre). Dimension SI : vitesse (profondeur / temps), facteur = 1e-3 / 86400 m/s.', NULL, '{"BIPM SI Brochure 9eme edition (2019)","OMM/WMO Guide to Meteorological Instruments and Methods of Observation (WMO-No. 8)"}', true, NULL, '2026-09-17 06:04:53.512876+00', NULL, '2026-09-17 06:04:53.512876+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (159, 'microgramme_par_metre_cube', 'microgramme par metre cube', 'µg/m³', 'concentration_massique', 'SI', false, 0.000000001000000000000000000000, 0.000000000000000000000000000000, 'kilogramme_par_metre_cube', 'Concentration massique de particules dans l''air (masse de particules par volume d''air). Sous-multiple decimal du kg/m3 : 1 ug/m3 = 1e-9 kg/m3. Unite standard de la qualite de l''air (PM2.5 / PM10).', NULL, '{"BIPM SI Brochure 9eme edition (2019)","WHO Global Air Quality Guidelines (2021)"}', true, NULL, '2026-09-17 06:04:55.363582+00', NULL, '2026-09-17 06:04:55.363582+00', NULL);
INSERT INTO public.unites (id, code, libelle, symbole, grandeur, systeme, est_unite_de_base, facteur_conversion_si, decalage_conversion_si, code_unite_si, note_methodologique, contexte_usage, references_normatives, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (160, 'kwh_par_kwc_periode', 'kilowattheure par kilowatt-crête sur la période', 'kWh/kWc', 'productible_specifique_periode', 'composee_mixte', false, 3600.000000000000000000000000000000, 0.000000000000000000000000000000, 'seconde', 'Productible spécifique d''un système photovoltaïque exprimé en total sur la période de la mesure (mensuelle ou annuelle), sans normalisation journalière. Unité introduite pour corriger le drift d''étiquette de productible_specifique_theorique (les valeurs stockées sont des totaux par période, pas des moyennes journalières). Dimensionnellement identique à l''heure (facteur SI = 3600), comme l''heure équivalente pleine.', NULL, '{"IEC 61724-1 (Photovoltaic system performance - Part 1 : Monitoring)","IEA PVPS Task 13"}', true, NULL, '2026-09-17 06:07:41.703362+00', NULL, '2026-09-17 06:07:41.703362+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (1, 'hep', 'Heures équivalentes pleines', 156, 'F1', 'stockee', NULL, 1, 'Heures équivalentes pleines (HEP). Quotient de l''énergie produite par la puissance crête nominale d''un système photovoltaïque, exprimé en heures équivalentes. Cadence annuelle ou mensuelle selon la série.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (2, 'kt', 'Indice de clarté', 122, 'F1', 'stockee', NULL, 1, 'Indice de clarté Kt. Rapport entre l''irradiation globale horizontale au sol et l''irradiation extraterrestre. Ingéré directement depuis NASA POWER (paramètre `ALLSKY_KT`).', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (3, 'fraction_diffuse', 'Fraction diffuse', 122, 'F1', 'stockee', NULL, 1, 'Fraction diffuse de l''irradiation. Rapport entre l''irradiation horizontale diffuse (DHI) et l''irradiation horizontale globale (GHI). DHI source CERES SYN1deg.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (5, 'variabilite_journaliere', 'Indice de variabilité journalière', 122, 'F1', 'stockee', NULL, 1, 'Indice de variabilité journalière. Coefficient de variation de l''irradiation journalière sur la période, sans dimension. Utilisé pour le dimensionnement des systèmes avec stockage.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (7, 'ecart_relatif_referentiel', 'Écart relatif au référentiel Kuma', 123, 'F1', 'calculee_volee', NULL, 1, 'Écart relatif au référentiel Kuma. Différence entre la valeur d''une série et la moyenne de cette grandeur calculée sur l''ensemble des sites du référentiel Kuma, exprimée en pourcent. Calculée à la volée, dépendante du périmètre courant.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (9, 'indicateur_qualite_donnees', 'Indicateur qualité du jeu de données', 122, 'F1', 'stockee', NULL, 1, 'Indicateur qualité du jeu de données. Score éditorial Kuma de 1 (faible) à 5 (excellent) caractérisant la fiabilité d''une série mesurée. Métrique de transparence éditoriale.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (10, 'poa_parametrable', 'POA paramétrable', 63, 'F2', 'calculee_volee', NULL, 1, 'Plane of Array (POA) paramétrable. Irradiation incidente sur une surface inclinée selon les paramètres utilisateur (inclinaison, azimut, albédo). Calculée à la volée à partir de GHI, DNI et DHI selon le modèle de transposition retenu.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (11, 'productible_correction_thermique', 'Productible avec correction thermique', 154, 'F2', 'calculee_volee', NULL, 1, 'Productible spécifique journalier avec correction thermique. Énergie produite par kilowatt-crête, ajustée selon le coefficient de température et la NOCT du module fournis par l''utilisateur. Calculée à la volée.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (12, 'productible_pr_fourni', 'Productible avec PR fourni', 154, 'F2', 'calculee_volee', NULL, 1, 'Productible spécifique journalier avec PR fourni. Énergie produite par kilowatt-crête, ajustée selon le Performance Ratio fourni par l''utilisateur. Calculée à la volée.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (13, 'energie_utile_ecs', 'Énergie utile ECS', 63, 'F2', 'calculee_volee', NULL, 1, 'Énergie utile pour eau chaude sanitaire (ECS). Énergie thermique délivrée par mètre carré de collecteur solaire, ajustée selon le rendement optique et les pertes thermiques fournis par l''utilisateur. Calculée à la volée.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (14, 'degre_jour_climatisation', 'Degrés-jours de climatisation', 157, 'F2', 'calculee_volee', NULL, 1, 'Degrés-jours de climatisation. Cumul des écarts positifs entre la température journalière moyenne et la température de référence de climatisation (base) précisée par l''utilisateur. Calculé à la volée selon la convention ISO 15927-6 (Part 6, Accumulated temperature differences).', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (15, 'humidex', 'Indice de confort thermique (Humidex)', 17, 'F1', 'stockee', NULL, 1, 'Indice de confort thermique Humidex. Indice combinant température et humidité, exprimé en degrés Celsius apparents. Formule Masterton & Richardson (1979), Service de l''environnement atmosphérique (AES) d''Environnement Canada.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (16, 'ghi', 'Irradiation globale horizontale', 63, 'F1', 'stockee', NULL, 1, 'Irradiation globale horizontale (Global Horizontal Irradiance) journalière. Donnée brute ingérée depuis NASA POWER paramètre ALLSKY_SFC_SW_DWN (méthode satellitaire CERES SYN1deg + FLASHFlux) ou autre source de méthode équivalente. Lieu de stockage physique : mesures_ressource (convention cadrage Q7 v1.3 pour methode_collecte=modele_satellitaire).', true, NULL, '2026-09-17 06:04:12.603656+00', NULL, '2026-09-17 06:04:12.603656+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (17, 'dni', 'Irradiation normale directe', 63, 'F1', 'stockee', NULL, 1, 'Irradiation normale directe (Direct Normal Irradiance) journalière. Donnée brute ingérée depuis NASA POWER paramètre ALLSKY_SFC_SW_DNI ou autre source de méthode équivalente. Entrée du calcul Plane of Array (POA) paramétrable F2.', true, NULL, '2026-09-17 06:04:12.603656+00', NULL, '2026-09-17 06:04:12.603656+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (18, 'dhi', 'Irradiation diffuse horizontale', 63, 'F1', 'stockee', NULL, 1, 'Irradiation diffuse horizontale (Diffuse Horizontal Irradiance) journalière. Donnée brute ingérée depuis NASA POWER paramètre ALLSKY_SFC_SW_DIFF (composant diffus CERES SYN1deg) ou autre source de méthode équivalente. Entrée du calcul fraction diffuse F1 stockée et du POA paramétrable F2.', true, NULL, '2026-09-17 06:04:12.603656+00', NULL, '2026-09-17 06:04:12.603656+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (19, 't2m', 'Température à 2 mètres', 17, 'F1', 'stockee', NULL, 1, 'Température moyenne journalière à 2 mètres au-dessus de la surface. Donnée brute ingérée depuis NASA POWER paramètre T2M (source MERRA-2 GMAO) ou autre source équivalente. Entrée du calcul humidex F1 stockée et du productible avec correction thermique F2.', true, NULL, '2026-09-17 06:04:12.603656+00', NULL, '2026-09-17 06:04:12.603656+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (20, 'rh2m', 'Humidité relative à 2 mètres', 123, 'F1', 'stockee', NULL, 1, 'Humidité relative moyenne journalière à 2 mètres au-dessus de la surface. Donnée brute ingérée depuis NASA POWER paramètre RH2M (source MERRA-2 GMAO) ou autre source équivalente. Entrée du calcul humidex F1 stockée (formule Masterton & Richardson 1979).', true, NULL, '2026-09-17 06:04:12.603656+00', NULL, '2026-09-17 06:04:12.603656+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (6, 'productible_mensuel', 'Productible mensuel', 155, 'F1', 'stockee', NULL, 1, 'Productible mensuel. Énergie produite par kilowatt-crête sur un mois calendaire, calculée pour chacun des 12 mois de l''année. Caractérise la saisonnalité énergétique d''un site.', false, '2026-09-17 06:04:24.362685+00', '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (8, 'rang_referentiel', 'Rang dans le référentiel Kuma', 122, 'F1', 'calculee_volee', NULL, 1, 'Rang dans le référentiel Kuma. Position ordinale d''une série dans le classement des sites du référentiel pour une grandeur donnée. Calculé à la volée, dépendant du périmètre courant. [D-39 : desactivee en migration 042, decomposee en rang_referentiel_temporel + rang_referentiel_spatial cf. spec 1-7 PR #54.]', false, '2026-09-17 06:04:25.259934+00', '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (4, 'productible_specifique_theorique', 'Productible spécifique théorique', 160, 'F1', 'stockee', NULL, 1, 'Productible spécifique théorique journalier. Énergie attendue d''un système photovoltaïque par kilowatt-crête installé, calculée par un modèle de performance simplifié à partir des seules données d''irradiation, sans correction thermique ni autre paramètre. Valeur de référence éditoriale.', true, NULL, '2026-09-17 06:04:12.520887+00', NULL, '2026-09-17 06:04:12.520887+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (21, 'rang_referentiel_temporel', 'Rang temporel dans la climatologie', 122, 'F1', 'calculee_volee', NULL, 1, 'Rang temporel dans la climatologie de reference (percentile calcule par mois calendrier sur la distribution NASA POWER 1991-2020 par localite). Formule type 7 numpy/R : p = (rang - 1) / (n - 1) x 100, capping [0, 100]. Plage de calcul phase 1 : 2021-2025 sur les 6 villes pilotes guineennes. Decomposition de rang_referentiel singulier seede en 1-1C (D-39 fermee dans le meme cycle 1-7b). Cf. note methodologique amont PR #53 et spec 1-7 PR #54.', true, NULL, '2026-09-17 06:04:25.259934+00', NULL, '2026-09-17 06:04:25.259934+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (22, 'rang_referentiel_spatial', 'Rang spatial dans le perimetre Kuma', 122, 'F1', 'calculee_volee', NULL, 1, 'Rang spatial dans le perimetre Kuma (rang ordinal 1-6 parmi les 6 villes pilotes guineennes pour le meme mois). Calcule a la volee a partir des mesures NASA POWER 2021-2025 agregees mensuellement. Decomposition de rang_referentiel singulier seede en 1-1C (D-39 fermee dans le meme cycle 1-7b). Cf. note methodologique amont PR #53 et spec 1-7 PR #54.', true, NULL, '2026-09-17 06:04:25.259934+00', NULL, '2026-09-17 06:04:25.259934+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (23, 'vent_2m', 'Vent à 2 mètres', 99, 'F1', 'stockee', NULL, 1, 'Vitesse moyenne journalière du vent à 2 mètres au-dessus de la surface. Donnée brute ingérée depuis NASA POWER paramètre WS2M (source MERRA-2 GMAO). Entrée du modèle Faiman 2008 pour la température cellule de la grandeur F2 productible_correction_thermique (résorbe la dette D-43).', true, NULL, '2026-09-17 06:04:26.102079+00', NULL, '2026-09-17 06:04:26.102079+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (24, 'vent_10m', 'Vent à 10 mètres', 99, 'F1', 'stockee', NULL, 1, 'Vitesse moyenne journalière du vent à 10 mètres au-dessus de la surface. Donnée brute ingérée depuis NASA POWER paramètre WS10M (source MERRA-2 GMAO). Cohorte vent complémentaire pour usages potentiels éoliens ; hors périmètre Phase 2 (solaire uniquement).', true, NULL, '2026-09-17 06:04:26.102079+00', NULL, '2026-09-17 06:04:26.102079+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (25, 'albedo_surface', 'Albédo de surface', 122, 'F1', 'stockee', NULL, 1, 'Albédo de surface (réflectivité du sol, sans dimension, plage théorique [0, 1]). Donnée brute ingérée depuis NASA POWER paramètre ALLSKY_SRF_ALB. Entrée de la composante réfléchie pour les modèles POA et préparation du bifacial (Phase 2 vague 5).', true, NULL, '2026-09-17 06:04:26.102079+00', NULL, '2026-09-17 06:04:26.102079+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (26, 'ghi_exceedance', 'Exceedance inter-annuelle de l''irradiation annuelle (GHI)', 64, 'F1', 'calculee_volee', NULL, 1, 'Exceedance inter-annuelle de l''irradiation annuelle dérivée de la série GHI mensuelle 1991-2020 (NASA POWER, climatologie OMM). Pour une ville pilote donnée, le calcul reconstruit les 30 totaux annuels (somme des 12 mensuels pondérée par le nombre de jours du mois, années bissextiles incluses) puis extrait deux percentiles : P50 (médiane) et P90 (valeur dépassée 90 % des années = 10ᵉ percentile, scénario conservateur). Grandeur calculée à la volée à chaque appel API, jamais stockée. Indicateur de variabilité inter-annuelle, ne propage pas l''incertitude de modèle ; ce n''est pas un P90 bancable complet.', true, NULL, '2026-09-17 06:04:31.485644+00', NULL, '2026-09-17 06:04:31.485644+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (27, 'ecart_relatif_dni_cams', 'Ecart relatif DNI CAMS vs NASA POWER', 123, 'F1', 'calculee_volee', NULL, 1, 'Ecart relatif inter-source du DNI entre NASA POWER (primaire) et CAMS Radiation (reference d''ecart aerosol-corrigee), formule (nasa - cams)/cams x 100, en pourcent signe. Calculee a la volee, materialisee dans grandeurs_metier par (annee, mois) sur la fenetre commune 2004-2020 (6 villes pilotes). Famille F1.', true, NULL, '2026-09-17 06:04:42.031704+00', NULL, '2026-09-17 06:04:42.031704+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (28, 'poa_bifacial', 'POA bifacial (irradiance globale row-aware)', 63, 'F2', 'calculee_volee', NULL, 1, 'POA global bifacial d''un champ de rangees (modele infinite-sheds row-aware, pvlib.bifacial). Irradiation incidente face avant + gain face arriere (rayonnement reflechi par le sol), selon la geometrie de rangees (gcr, hauteur, pitch), la bifacialite du module et l''albedo. Distinct du poa_parametrable mono-plan. Calculee a la volee. Famille F2.', true, NULL, '2026-09-17 06:04:53.507627+00', NULL, '2026-09-17 06:04:53.507627+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (29, 'precipitation', 'Precipitation journaliere', 158, 'F1', 'stockee', NULL, 1, 'Hauteur de precipitation journaliere (mm/jour). Donnee brute ingeree depuis NASA POWER parametre PRECTOTCORR (Precipitation Corrected, source amont MERRA-2 GMAO / IMERG). Entree pluie du modele de salissure HSU (pvlib.soiling.hsu) pour la grandeur proxy taux_salissure_proxy (Vague 5 soiling Lot C). Confiance B (modele satellitaire).', true, NULL, '2026-09-17 06:04:53.512876+00', NULL, '2026-09-17 06:04:53.512876+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (30, 'pm2_5', 'Particules fines PM2.5', 159, 'F1', 'stockee', NULL, 1, 'Concentration massique journaliere de particules fines de diametre <= 2,5 um (ug/m3). Donnee brute EAC4 (ADS Copernicus), moyenne journaliere du pas 3-horaire. Entree particules du modele de salissure HSU (pvlib.soiling.hsu) pour la grandeur proxy taux_salissure_proxy (Vague 5 soiling Lot C). Confiance B (modele satellitaire).', true, NULL, '2026-09-17 06:04:55.363582+00', NULL, '2026-09-17 06:04:55.363582+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (31, 'pm10', 'Particules PM10', 159, 'F1', 'stockee', NULL, 1, 'Concentration massique journaliere de particules de diametre <= 10 um (ug/m3). Donnee brute EAC4 (ADS Copernicus), moyenne journaliere du pas 3-horaire. Entree particules du modele de salissure HSU (pvlib.soiling.hsu) pour la grandeur proxy taux_salissure_proxy (Vague 5 soiling Lot C). Inclut les PM2.5 (PM10 >= PM2.5). Confiance B.', true, NULL, '2026-09-17 06:04:55.363582+00', NULL, '2026-09-17 06:04:55.363582+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (32, 'taux_salissure_proxy', 'Proxy de salissure (perte de transmission, %)', 123, 'F1', 'calculee_volee', NULL, 1, 'Proxy de salissure des modules PV : perte de transmission par salissure, en % = (1 - ratio HSU) x 100. Modele HSU (pvlib.soiling.hsu, Coello & Boyle 2019) a partir des PM2.5/PM10 EAC4 (convertis ug/m3 -> g/m3, unite attendue par pvlib) et de la pluie NASA POWER (mm). F1 calculee_volee, confiance B derivee. Tilt et seuil de nettoyage par defaut documentes (10 deg, 1 mm). Caveats L-SOIL : proxy modele (pas une mesure de salissure, terrain) ; spin-up (HSU demarre propre, premiers jours sous-estimes, L-SOIL-3) ; grille EAC4 grossiere 0,75 deg (L-SOIL-4). ', true, NULL, '2026-09-17 06:04:58.673525+00', NULL, '2026-09-17 06:04:58.673525+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (33, 'pr_realiste', 'PR realiste saisonnier (PR effectif site-specifique)', 122, 'F1', 'calculee_volee', NULL, 1, 'PR effectif site-specifique = PR_fourni x ratio_T x (1 - salissure), ratio sans dimension. Modes de correction aucune / temperature / salissure / temperature_salissure. Compose le facteur thermique NOCT (Ross 1980, productible_correction_thermique) et le proxy de salissure HSU (taux_salissure_proxy, Lot C). La courbe mensuelle est la ''PR saisonniere'' (creux Harmattan). F1 calculee_volee, confiance B. Doctrine PR-reference (anti double-comptage) : le PR_fourni est suppose hors salissure ET hors temperature ; corrections multiplicatives separables. Ne traite pas la correction meteo/climat.', true, NULL, '2026-09-17 06:04:58.676986+00', NULL, '2026-09-17 06:04:58.676986+00', NULL);
INSERT INTO public.grandeurs_referentiel (id, code, libelle, unite_id, famille, strategie_calcul, methode_calcul_doc, version_formule_actuelle, description, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (34, 'degenerescence_pixel', 'Degenerescence de pixel (nombre de jumeaux-pixel)', 122, 'F1', 'calculee_volee', NULL, 1, 'Indicateur d''honnetete structurelle de l''atlas : pour une (localite, source, parametre), nombre d''autres points partageant la meme cellule source (0 = point reellement resolu). Detection empirique par identite de series climato mensuelles sur grille fixe (NASA radiation CERES 1deg, meteo MERRA 0.5deg). Services interpoles (SARAH-3 / CAMS 5 km) : compte 0 + caveat de resolution. F1 calculee_volee, materialisee statique, confiance B (A reservee aux mesures terrain ; exactitude dite par caveat, pas par une remontee en A).', true, NULL, '2026-09-17 06:06:29.672608+00', NULL, '2026-09-17 06:06:29.672608+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (1, 'nasa_power', 'NASA POWER - Prediction Of Worldwide Energy Resources : Solar and Meteorological Data Archive', NULL, 'NASA Langley Research Center (LaRC)', 'base_donnees', NULL, '2026-05-10', 'https://power.larc.nasa.gov/', NULL, NULL, '{"acces": "API REST publique gratuite (rate-limited), Data Access Viewer (DAV), AWS Open Data Registry", "granularite_spatiale": "0.5° × 0.625° (météorologie, MERRA-2) ; 1° × 1° (solaire, CERES SYN1deg)", "granularite_temporelle": "horaire | journalier | mensuel | climatologique", "couverture_temporelle_fin": "ongoing (NRT, climat-quality après 2-3 mois)", "couverture_temporelle_debut": "1984-01-01"}', 'haute', 'en', 'Source primaire du substrat physique guinéen. Objet calibré au sens des 3 couches Kuma (couche A - calibration). NASA Langley Research Center (LaRC) opérateur, programme NASA Earth Science Division. Version actuelle : POWER Data v10. Bifurcation des couvertures temporelles selon la communauté de paramètres : (a) Météorologie 1981-01-01 → présent (source amont : NASA GMAO MERRA-2) ; (b) Solaire 1984-01-01 → présent (sources amont : NASA SRB 4.0-IP 1984-2000, puis CERES SYN1deg + FLASHFlux à partir de 2001). La valeur couverture_temporelle_debut du JSONB retient 1984-01-01, valeur effective pour la communauté Kuma phase 1 = RE (Renewable Energy, focus solaire). Communautés exposées par NASA POWER : AG (Agroclimatology), RE (Renewable Energy), SB (Sustainable Buildings). Convention de communauté Kuma à acter en spec préparatoire 1-2a. Méthodologie publique documentée sur `power.larc.nasa.gov/docs/methodology/`. Convention de code DT-1 : `nasa_power` retient l''organisme producteur scientifique (NASA LaRC) + thème (POWER, nom du projet). Pas d''année dans le code : la base évolue par versions glissantes (v10 actuelle), sans rupture éditoriale justifiant un nouveau code par millésime. Acknowledgement officiel (cf. `power.larc.nasa.gov/docs/referencing/`) à inclure dans toute publication exploitant les données : « The data was obtained from National Aeronautics and Space Administration (NASA) Langley Research Center''s Prediction Of Worldwide Energy Resources (POWER) project funded through the NASA Earth Science Division. » NASA POWER demande également de spécifier le triplet service name + version number + date accessed (exemple : « obtained from the POWER Project''s Hourly 2.x.x version on 2026-05-10 »). Cette exigence se traduira en convention applicative phase 1-2b pour les réponses API Kuma qui exposent des données dérivées de NASA POWER. Pas de mention β2 normée DT-8 (source primaire phase 1 du substrat physique guinéen, opérationnelle phase 1 pour solaire + climat, hors liste des 4 sources hydro structurelles). Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (2, 'ecmwf_era5', 'ECMWF ERA5 - Fifth Generation Atmospheric Reanalysis of the Global Climate (Copernicus Climate Change Service)', NULL, 'European Centre for Medium-Range Weather Forecasts (ECMWF)', 'base_donnees', 2018, '2026-05-10', 'https://cds.climate.copernicus.eu/datasets/reanalysis-era5-single-levels', '10.24381/cds.adbb2d47', NULL, '{"acces": "Copernicus Climate Data Store (CDS) API + portail web, gratuit avec inscription, licence Copernicus (acknowledgment requis)", "granularite_spatiale": "0.25° × 0.25° (CDS regridded) ; 31 km natif (grille gaussienne réduite TCo639) ; 137 niveaux verticaux jusqu''à 0.01 hPa (80 km)", "granularite_temporelle": "horaire (native) | journalier (statistiques pré-calculées) | mensuel (moyennes pré-calculées)", "couverture_temporelle_fin": "ongoing (latence 5 jours ; release préliminaire ERA5T pouvant différer de la version finale 2-3 mois plus tard)", "couverture_temporelle_debut": "1940-01-01"}', 'haute', 'en', 'Source de cross-check principal au sens des 3 couches Kuma (couche B). Compatible solaire + climat (opérationnel phase 1) ; paramètres hydro (precipitation, évapotranspiration, runoff via ERA5-Land) conçus pour cross-check β2 mais non activés en phase 1 (cf. CdC § 4.1). Producteur scientifique : ECMWF, organisation intergouvernementale européenne (32 États membres et coopérants), opérant pour le Copernicus Climate Change Service (C3S) financé par l''Union européenne. Distribution publique via la Climate Data Store (CDS, `cds.climate.copernicus.eu`). Article scientifique de référence : Hersbach, H. et al. (2020), « The ERA5 global reanalysis », Q.J.R. Meteorol. Soc., 146: 1999-2049, DOI : 10.1002/qj.3803. Article extension à 1940 : Bell, B. et al. (2021), « The ERA5 global reanalysis: Preliminary extension to 1950 », Q.J.R. Meteorol. Soc., 147(741): 4186-4227, DOI : 10.1002/qj.4174. Convention de code DT-1 : `ecmwf_era5` retient le producteur scientifique (ECMWF, tutelle internationale). Le distributeur public (Copernicus C3S) est un programme opéré par ECMWF, donc pas de tutelle distincte. Code conforme à l''ordre DT-1 : tutelle internationale > responsable actuel > producteur historique. Variantes ERA5 disponibles sur le CDS, chacune avec DOI distinct : single levels (DOI retenu, dataset pivot Kuma phase 1), pressure levels, monthly means, daily statistics, time-series, ensemble. Pour 1-1E, fiche pivot = single levels (couverture paramètres la plus large incluant radiation solaire, températures, vents, humidité). ERA5-Land (variante land-only haute résolution : 9 km natif / 0.1° × 0.1° regridded, couverture 1950-présent, 50 variables surface dont runoff, soil moisture, evaporation) : non seedée dans la présente fiche. À acter potentiellement comme source distincte `ecmwf_era5_land` en future passe (passe complémentaire 1-1E ou phase 2+) pour appui spécifique sur le vecteur hydro β2 (DOI ERA5-Land monthly : 10.24381/cds.68d2bb30 ; cf. Muñoz Sabater 2019). Décision technique à acter (DT-X potentielle) si besoin avéré phase 2+. En 1-1E, périmètre source = ERA5 atmospheric reanalysis uniquement. Acknowledgement requis (licence Copernicus) : « Generated using Copernicus Climate Change Service Information [Year] ». À intégrer en convention applicative phase 1-2b pour les réponses API Kuma exposant des données dérivées d''ERA5. Pas de mention β2 normée DT-8 (ERA5 n''appartient pas à la liste des 4 sources hydro structurelles ; il est multi-vecteurs et opérationnel phase 1 pour solaire + climat). L''usage hydro d''ERA5 est cependant conçu pour cross-check référentiel sans activation phase 1. Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (4, 'iec_61724_1_2021', 'IEC 61724-1:2021 - Photovoltaic system performance - Part 1: Monitoring (Edition 2.0)', NULL, 'International Electrotechnical Commission (IEC)', 'norme_technique', 2021, '2026-05-10', 'https://webstore.iec.ch/en/publication/65561', NULL, '9782832210025', '{"editeur": "International Electrotechnical Commission (IEC)", "comite_technique": "TC 82 - Solar photovoltaic energy systems", "edition_millesimee": "2021 (Edition 2.0)"}', 'haute', 'en', 'Norme opérationnelle phase 1 pour le vecteur solaire. Couche C des 3 couches Kuma (post-traitement éditorial Kuma : conventions méthodologiques IEC appliquées aux données brutes pour produire les grandeurs métier finales - performance ratio, yield, irradiance d''incidence, etc.). Définit la terminologie, les équipements, les méthodes de monitoring et d''analyse de la performance des systèmes photovoltaïques. Définit deux classes d''exactitude pour les systèmes de monitoring (Class A et Class B) à partir de la 2ème édition (l''ancienne Class C de l''édition 2017 est renommée Class B en 2021, l''ancienne Class B 2017 étant durcie). ICS code : 27.160 (Solar energy engineering). Comité technique : IEC TC 82 (Solar photovoltaic energy systems). Édition 2.0 publiée le 2021-07-21, annule et remplace l''édition 1.0 de 2017. Évolutions techniques majeures 2021 vs 2017 : introduction du monitoring des systèmes bifaciaux, mise à jour des exigences sur les capteurs d''irradiance, mise à jour des mesures de salissure (soiling) basée sur nouvelles technologies, passage de 3 à 2 classes d''exactitude (Class A et Class B) - l''ancienne Class C de 2017 est renommée en nouvelle Class B de 2021, l''ancienne Class B 2017 étant durcie. Convention de code DT-1 : `iec_61724_1_2021` retient l''organisme producteur (IEC, tutelle internationale), la référence (61724 = série « PV system performance », couvrant Part 1 Monitoring + Part 2 Capacity evaluation method TS:2016 + Part 3 Energy evaluation method TS:2016 ; Part 1 traite spécifiquement du monitoring opérationnel), la partie (1 = Monitoring), et l''édition millésimée (2021). Présence de l''année dans le code, contrairement à `nasa_power` ou `ecmwf_era5` : justifiée parce que les éditions de normes sont des ruptures éditoriales avec changements techniques significatifs (2017 → 2021 ci-dessus), qui justifient un code distinct par millésime. Convention transverse normes éditées initialisée par cette fiche (1ère occurrence), confirmée sur les 3 normes éditées suivantes de la passe (`wmo_8_2024`, `iec_60041_1991`, `wmo_168_2008`). Cohérent avec DT-7 où metadonnees->>''edition_millesimee'' peut spécifier des amendements ultérieurs sans changer le code (par exemple « 2021+A1:YYYY » si amendement ultérieur, code stable). ISBN natif IEC `9782832210025` (vérifié par consultation du webstore IEC le 2026-05-10 : page produit officielle https://webstore.iec.ch/en/publication/65561 expose l''ISBN dans la fiche produit). Les dérivées nationales BSI EN IEC 61724-1:2021 ont un ISBN distinct `978-0-539-06005-8` mais sortent du périmètre source IEC (cf. DT-9 du CdC v2.2). Accès au texte intégral : paywall IEC Webstore (478 USD pour la version standard, 635 USD pour la version Redline avec changements 2017→2021 trackés). Page produit IEC publique fournit les métadonnées canoniques (titre, abstract, comité, ICS, ISBN, édition). GF-1 applicable : source primaire (texte intégral) inatteignable sans achat ; métadonnées vérifiables publiquement. Citation canonique : « IEC 61724-1:2021, Photovoltaic system performance - Part 1: Monitoring, International Electrotechnical Commission, Edition 2.0, July 2021 ». Convention applicative phase 1-2b : application des conventions PV monitoring IEC 61724-1:2021 (Class A/B, exigences irradiance, mesures soiling, calcul performance ratio) à propager dans les réponses API Kuma calculant des grandeurs métier solaires (couche C - post-traitement éditorial). Pas de mention β2 normée DT-8 (norme solaire opérationnelle phase 1, hors liste des 4 sources hydro structurelles). Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (5, 'wmo_8_2024', 'WMO-No.8 (CIMO Guide) - Guide to Instruments and Methods of Observation, Volume I - Measurement of Meteorological Variables, 2024 edition', NULL, 'World Meteorological Organization (WMO)', 'norme_technique', 2024, '2026-05-10', 'https://library.wmo.int/idurl/4/68695', '10.59327/WMO/CIMO/1', '9789263100085', '{"editeur": "World Meteorological Organization (WMO)", "comite_technique": "INFCOM/SC-MINT (Standing Committee on Measurements, Instrumentation and Traceability) - Editorial Board ; anciennement CIMO (Commission for Instruments and Methods of Observation)", "edition_millesimee": "2024 edition (digital, 601 pages - chiffre attribué au Volume I, à reconfirmer en passe 2 ; 5 volumes depuis 2018, scope fiche = Volume I)"}', 'haute', 'en', 'Méta-norme métrologique météo opérationnelle phase 1 (vecteur solaire + climat de base). Couche C des 3 couches Kuma (post-traitement éditorial Kuma : conventions WMO appliquées aux mesures météo pour produire les grandeurs métier conformes aux usages internationaux). Surnommé « CIMO Guide » (héritage du nom historique de la Commission for Instruments and Methods of Observation, désormais INFCOM/SC-MINT depuis la réforme WMO 2019). Scope de la présente fiche : Volume I - Measurement of Meteorological Variables (température, pression, humidité, vent surface, précipitations), édition 2024 finalisée. C''est le volume pertinent pour Kuma phase 1 (mesures météo de surface). Le DOI `10.59327/WMO/CIMO/1` et l''ISBN `978-92-63-10008-5` sont scope Volume I uniquement (le suffixe `/1` du DOI WMO/CIMO suit probablement le numéro de volume - à confirmer comme pattern transverse). Les autres volumes ont des éditions distinctes au moment de la compilation (mai 2026) : Volumes II-III « Provisional 2024 Edition » en cours de validation INFCOM-3 (Members'' review en novembre 2025) ; Volume IV édition 2021 ; Volume V à confirmer. Si un usage Kuma futur nécessite un de ces autres volumes, créer une fiche dédiée avec ses identifiants propres (DT-X potentielle). Multilingue officiel : anglais (texte de référence), arabe, chinois, français, espagnol, russe - versions traduites disponibles via la WMO Library. Topics indexés : GSICS (Global Space-based Inter-Calibration System), AWOS (Automated Weather Observing System), WIGOS (WMO Integrated Global Observing System), Hydrometeorological/Meteorological instruments, Methodology. Convention de code DT-1 : `wmo_8_2024` retient l''organisme (WMO, tutelle internationale), la référence (8 = numéro de publication officielle WMO), l''édition millésimée (2024). Présence de l''année dans le code : justifiée parce que les éditions WMO sont des ruptures éditoriales avec changements techniques significatifs, cohérent avec la convention déjà appliquée à `iec_61724_1_2021`. Convention transverse normes éditées confirmée par 2ème occurrence. Accès : libre et gratuit, PDF téléchargeable directement depuis library.wmo.int - contraste majeur avec IEC 61724-1:2021 (paywall 478 USD). Aucun GF-1 applicable. Anciennes éditions accessibles sur demande à `library@wmo.int`. DOI canonique : `10.59327/WMO/CIMO/1` - première source structurelle de la passe disposant d''un DOI canonique fiable (à la différence de NASA POWER qui utilise une citation textuelle, et IEC 61724-1:2021 qui s''identifie par son code IEC sans DOI). Pattern transverse à observer : les publications WMO modernes (post-2018) sont systématiquement DOI''ées via Crossref. Drift par rapport au CdC § 2.2 : le CdC énumère le code `wmo_8_2023` (provisoire à la date de cadrage initial mai 2026). L''édition publiée effective est 2024. Code corrigé en `wmo_8_2024` dans la présente fiche. Amendement CdC § 2.2 acté en passe consolidation post-compilation. Aucun impact doctrinal - seul le millésime du code change, l''identité de la source et son rôle dans la cartographie § 4.2 sont inchangés. Anecdote projet : la consultation Members'' review de la Preliminary 2024 Edition (novembre 2023 - mars 2024) a inclus des commentaires officiels de la Guinée sur Volume I Chapitres 6 et 7 et Volume III Chapitre 5, parmi un petit groupe de pays (Chine, Allemagne, Hong Kong, Italie, Japon, Corée du Sud, UK). Confirme l''engagement actif de l''ANM Guinée auprès de la WMO et l''alignement éditorial Kuma sur des normes que la Guinée elle-même contribue à établir. Citation canonique : « WMO, 2024 : Guide to Instruments and Methods of Observation (WMO-No. 8), 2024 edition. World Meteorological Organization, Geneva. ISBN 978-92-63-10008-5. DOI : 10.59327/WMO/CIMO/1 ». Convention applicative phase 1-2b : la citation canonique de WMO-No.8 ci-dessus est à propager dans les réponses API Kuma exposant des données traitées selon les conventions du CIMO Guide (calibrations d''instruments météo, méthodes d''observation standards WMO). Pas de mention β2 normée DT-8 (méta-norme météo opérationnelle phase 1, hors liste des 4 sources hydro structurelles). Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (6, 'wmo_grdc', 'WMO/GRDC - Global Runoff Data Centre (Global Runoff Database)', NULL, 'Global Runoff Data Centre (GRDC), opéré par le Federal Institute of Hydrology (Bundesanstalt für Gewässerkunde - BfG), Koblenz, Allemagne, sous mandat de la World Meteorological Organization (WMO)', 'base_donnees', NULL, '2026-05-10', 'https://grdc.bafg.de/', NULL, NULL, '{"acces": "demande via Data Portal `grdc.bafg.de/data/data_portal/` (formulaire + agreement Terms of Use + Data Sharing Conditions) ; download link envoyé sous 24h par mail ; usage non-commercial uniquement ; non-redistribution ; format WaterML2 (standard WMO/OGC) parmi autres formats", "granularite_spatiale": "ponctuelle (gauging stations) ; > 11 000 stations à décembre 2025 (10 836 en janvier 2025, croissance soutenue avec 1772 stations mises à jour en 2024) ; 43 pays ont contribué en 2025, 44 en 2024 selon GRDC reviews ; durée moyenne par station 40 ans selon historique GRDC ; en Guinée stations attendues sur Niger, Sénégal, Gambie, Konkouré. Détails complémentaires (nombre cumulé exact de pays contributeurs, durée moyenne précise, stations Guinée) à confirmer en passe 2 via database statistics GRDC ; cf. notes.", "granularite_temporelle": "journalier (mean daily discharge) | mensuel (mean monthly discharge)", "couverture_temporelle_fin": "ongoing (mises à jour continues, lag inhérent à la soumission par services hydrologiques nationaux)", "couverture_temporelle_debut": "1807 (la plus ancienne série en service est dans le bassin de la mer Baltique, selon paper BALTEX dataset Frontiers 2025 ; pays exact à confirmer en passe 2) ; couverture Guinée à confirmer en passe 2 (cf. notes)"}', 'haute', 'en', 'Source de référence structurelle (hydrologie) : schéma de validation conçu, population effective différée. Le pipeline hydro (ingestion des débits, calculs de productible, endpoints) n''est pas encore actif. Calibreur hydro principal au sens des 3 couches Kuma (couche A - calibration : référence terrain pour les modèles globaux de débit) ; rôle β2 phase 1 = référentiel uniquement, validation effective phase 2+. Source hydro structurelle 1/4 du périmètre β2 phase 1 (les 3 autres : `wwf_hydrosheds`, `iec_60041_1991`, `wmo_168_2008`). Histoire et gouvernance : GRDC créé officiellement opérationnel le 1988-11-14 ; lignée historique : Decade Hydrologique Internationale UNESCO (1965) → publication monumentale « The Discharge of Selected Rivers of the World » (1969-1984, avec mises à jour 1988 incorporant les nouvelles données dans la base GRDC opérationnelle) → Institute for Bioclimatology and Applied Meteorology, Université de Munich (1982) → transfert au BfG, Koblenz (1984) → opérationnel (1988). Mandat WMO acté par les Résolutions WMO Congress XII n° 21 (1995) et WMO Congress XIII n° 25 (1999). Endorsement WMO Climate Data Catalogue acté au Cg-18. Steering committee international encadrant les activités GRDC : WMO, UNESCO, UNEP, IAHS (International Association of Hydrological Sciences), partner data centres. Activité récente documentée : 15ème réunion du Steering Committee international tenue en juin 2024 (cf. GRDC Happy New Year 2025). WMO State of Global Water Resources reports (annuels, dernier publié le 18 septembre 2025 pour le millésime 2024) : GRDC en pilier de production. Croissance documentée du périmètre des rapports : 713 stations dans 26 pays en 2023 ; 2777 stations dans 41 pays en 2024. Datasets dérivés notables (cf. GRDC review 2025) : GRDC-Caravan extension (data paper 2025), BALTEX dataset (Frontiers 2025, extension régionale Baltique). Hors périmètre direct Kuma (régionaux européens) mais cités pour traçabilité - fiches Kuma futures possibles si pertinence avérée. Réseaux dérivés et programmes contributifs : GTN-R (Global Terrestrial Network for River Discharge) - composante hydro de GTN-H, officiellement accréditée « GCOS affiliated network » depuis mars 2025 ; GCOS Baseline River Network - > 300 gauging stations près des embouchures des grands fleuves mondiaux ; contributions à GEWEX (Global Energy and Water Exchanges Project), CliC (Climate and Cryosphere) du WCRP, GTN-H, GEOSS. Convention de code DT-1 : `wmo_grdc` retient la tutelle internationale (WMO, mandat scientifique supérieur acté par résolutions Cg) + thème (grdc). Le BfG (responsable opérationnel actuel) n''apparaît pas dans le code parce qu''il est opérateur technique sous mandat WMO. Cohérent avec l''ordre DT-1 : tutelle internationale > responsable actuel > producteur historique. Pattern transverse confirmé : pour les centres opérant sous auspices WMO/UNESCO/etc. avec hébergement national, retenir la tutelle internationale dans le code. Pas de DOI canonique pour la base GRDC. Pattern WMO post-2018 DOI''é (observé sur `wmo_8_2024` Volume I) non appliqué au GRDC - la base utilise une citation textuelle référencée comme NASA POWER. Ce contraste confirme que le pattern « DOI WMO post-2018 » est restreint aux publications-guides (CIMO Guide, etc.) et non aux bases de données opérationnelles. Citation officielle requise (Terms of Use GRDC) : « Global Runoff Data Centre of WMO. 56068 Koblenz, Germany: Federal Institute of Hydrology (BfG), [Date of retrieval: YYYY-MM-DD] ». Cette exigence se traduira en convention applicative phase 2+ pour les réponses API Kuma exposant des données dérivées du GRDC. Licence d''usage : non-commercial uniquement, non-redistribution à des tiers ou au grand public (y compris via Internet), citation requise. Conditions à vérifier précisément avec le projet Kuma au moment de l''activation phase 2+ (le statut de Kuma - média éditorial vs commercial - peut affecter l''éligibilité). GF-1 modéré : pas de paywall financier mais accès conditionnel à un agreement formel et un délai de 24h. Métadonnées du réseau (catalogue stations) accessibles via le portail. Données mesurées (séries de débits) accessibles via demande conforme. GF-4 non applicable : pas de millésime éditorial (base évolutive, contrastant avec normes IEC/WMO). Adresse postale : 56068 Koblenz, Germany. Email contact : `grdc@bafg.de`. Page contact officielle : `grdc.bafg.de/contact/`. Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (7, 'wwf_hydrosheds', 'WWF/HydroSHEDS - Hydrological data and maps based on SHuttle Elevation Derivatives at multiple Scales (réseaux fluviaux, bassins versants, MNT hydrologiquement conditionné)', NULL, 'World Wildlife Fund (WWF) - WWF US Conservation Science Program', 'base_donnees', 2008, '2026-05-10', 'https://www.hydrosheds.org/', NULL, NULL, '{"acces": "libre (free for both non-commercial and commercial use) ; download direct via data.hydrosheds.org ; alternative programmatique via Google Earth Engine (catalogue `WWF/HydroSHEDS/...` : 03VFDEM, 03CONDEM, 03DIR à 3 arc-sec ; 30CONDEM, 30DIR à 30 arc-sec ; HydroBASINS niveaux 9 et 12) ; License Agreement annexée à la Technical Documentation v1.4", "granularite_spatiale": "raster + vector multi-résolution : 3 arc-seconds (90 m à l''équateur) à 5 minutes (10 km) ; couverture globale à l''exception des régions > 60°N (qualité dégradée pour cause d''absence de données SRTM, fallback HYDRO1k USGS) ; couverture pleinement nominale pour la Guinée et l''Afrique de l''Ouest", "granularite_temporelle": "snapshot non temporel (référentiel topologique-hydrologique dérivé du DEM SRTM 2000-02-11/22, donc topologie représentative de l''état observé en février 2000)", "couverture_temporelle_fin": "2000-02-22 (snapshot SRTM ; représentativité topologique stable post-acquisition pour les bassins guinéens, hors aménagements hydroélectriques majeurs récents - Kaléta 2015, Souapiti 2020+, Amaria en construction - qui peuvent avoir modifié localement la topologie post-SRTM)", "couverture_temporelle_debut": "2000-02-11 (acquisition SRTM)"}', 'haute', 'en', 'Source de référence structurelle (hydrologie) : schéma de validation conçu, population effective différée. Le pipeline hydro (ingestion des débits, calculs de productible, endpoints) n''est pas encore actif. Topologie hydro principale au sens des 3 couches Kuma (couche C - post-traitement éditorial : référentiel structurel raster + vector pour réseau fluvial, bassins versants, ordres de Strahler, flow directions, flow accumulations) ; rôle β2 phase 1 = référentiel uniquement, validation effective phase 2+. Source hydro structurelle 2/4 du périmètre β2 phase 1 (les 3 autres : `wmo_grdc`, `iec_60041_1991`, `wmo_168_2008`). Distinction avec GRDC : HydroSHEDS = topologie sans mesures, GRDC = mesures stationnelles ponctuelles. Complémentaires. Datasets fournis (suite intégrée) : Core data products v1 (DEM original, DEM hydrologiquement conditionné, flow directions, flow accumulations, land mask, sink grids) ; Secondary data products (HydroBASINS - sous-bassins emboîtés hiérarchiques selon codification Pfafstetter ; HydroRIVERS - réseau fluvial vectorisé ; HydroLAKES - lacs et réservoirs globaux ; HydroATLAS - 50+ attributs hydro-environnementaux par tronçon de fleuve et sous-bassin) ; Produit dérivé récent (2025) : GLWD v2 (Global Lakes and Wetlands Database v2, Lehner et al. 2025), successeur de GLWD v1 (Lehner & Döll 2004), couvrant 18.2 millions de km² de zones humides à 15 arc-seconds (500 m à l''équateur). Hors scope phase 1 mais pertinent pour Kuma futur si extension agro-écologie / plaines inondables / mangroves côtières guinéennes (sous-mission potentielle phase 2+, à acter si besoin avéré). Hébergé sur hydrosheds.org. Versions : v1.1 (version courante effective phase 1) - Technical Documentation v1.4 (avril 2022) ; basée sur la mission Shuttle Radar Topography Mission (SRTM) 2000 à 3 arc-seconds (90 m) ; lignée 2008 publication initiale → améliorations itératives → v1.1 stable. v2.0 (en développement, release graduelle débutant en 2025 selon `hydrosheds.org/about`) - basée sur TanDEM-X (DLR) à résolution native 12 m, processed à 1 arc-seconde (30 m à l''équateur) - gain de résolution majeur vs v1 (3 arc-seconds = 90 m). Production en collaboration DLR + McGill University + Confluvio Consulting + WWF (calendrier initial 2024 dans certaines pages partenaires non actualisées). Régions > 60°N released en premier (zones les plus défaillantes en v1). Pour Kuma phase 1, v1.1 reste pleinement opérationnel sur la Guinée. v2 pourrait justifier une fiche distincte ou un amendement de fiche en passe ultérieure si la couverture Afrique de l''Ouest est released avec changements significatifs. Partenaires historiques v1 : WWF US, U.S. Geological Survey (USGS), International Centre for Tropical Agriculture (CIAT), The Nature Conservancy (TNC), Center for Environmental Systems Research, University of Kassel (Germany). Convention de code DT-1 : `wwf_hydrosheds` retient l''organisme producteur principal (WWF, responsable actuel et historique du programme HydroSHEDS) + thème (hydrosheds, nom du produit). Pas de tutelle internationale formelle (WWF est une ONG internationale mais pas une organisation intergouvernementale au sens strict de DT-1). Pas d''année dans le code (base évolutive par versions glissantes, pattern NASA POWER / ECMWF ERA5 / WMO-GRDC). v2 future ne justifiera probablement pas un nouveau code projet : la fiche métadonnée distinguera les versions. Citations scientifiques fondatrices (DOI requis si Kuma cite académiquement) : Lehner, B., Verdin, K., Jarvis, A. (2008). « New global hydrography derived from spaceborne elevation data. » Eos, Transactions American Geophysical Union, 89(10): 93-94. DOI : `10.1029/2008EO100001` (confirmé via AGU/Wiley page formelle Eos). Lehner, B., Grill, G. (2013). « Global river hydrography and network routing: baseline data and new approaches to study the world''s large river systems. » Hydrological Processes 27(15): 2171-2186 (HydroBASINS / HydroRIVERS) [DOI à confirmer en passe 2]. Licence : free for non-commercial and commercial use - contraste majeur avec WMO/GRDC qui interdit l''usage commercial. License Agreement annexée à la Technical Documentation v1.4 (Annexe A). Pour Kuma (statut éditorial à clarifier), la permissivité HydroSHEDS facilite l''usage transverse sans contrainte de licence. Citation suggérée (acknowledgement) : « HydroSHEDS database, World Wildlife Fund (WWF), version 1.1, accessed via hydrosheds.org on 2026-05-10. Lehner, B., Verdin, K., Jarvis, A. (2008). New global hydrography derived from spaceborne elevation data. Eos 89(10): 93-94. » Convention applicative phase 2+ : exposer la traçabilité des éléments topologiques hydro HydroSHEDS (réseau fluvial, bassins versants, ordres de Strahler, identifiants HydroBASINS Pfafstetter) dans les réponses API Kuma exposant des données hydrologiques structurées (couche C - post-traitement éditorial). Différé cohérent avec le statut β2 du vecteur hydro phase 1. GF-1 non applicable (accès libre direct via portail). GF-4 non applicable au code (base évolutive sans année), mais à appliquer à la version en métadonnées (v1.1 actuel à confirmer en passe 2). Spécificité Guinée : couverture pleinement nominale en v1.1 (3 arc-seconds), région < 60°N. Topologie représentative bonne pour les bassins Niger Supérieur, Sénégal (Bafing/Bakoye), Gambie, Konkouré, mais à confronter avec les aménagements hydroélectriques majeurs post-2000 (Kaléta, Souapiti, Amaria) qui modifient localement la topologie réelle vs SRTM 2000. Cohérence à acter en passe d''ingestion phase 2+. Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (8, 'iec_60041_1991', 'IEC 60041:1991 - Field acceptance tests to determine the hydraulic performance of hydraulic turbines, storage pumps and pump-turbines (Edition 3.0, avec Corrigendum 1 de mars 1996 inclus)', NULL, 'International Electrotechnical Commission (IEC)', 'norme_technique', 1991, '2026-05-10', 'https://webstore.iec.ch/en/publication/154', NULL, '283182222X', '{"editeur": "International Electrotechnical Commission (IEC)", "comite_technique": "TC 4 - Hydraulic turbines", "edition_millesimee": "3.0 (1991-11-30) avec Corrigendum 1 (mars 1996) ; Stability date 2025 - date de revue planifiée par l''IEC, pas date de remplacement ; norme courante en vigueur à mai 2026 [À reverifier en passe 2 phase 2+ si une nouvelle édition a été publiée]"}', 'haute', 'en', 'Source de référence structurelle (hydrologie) : schéma de validation conçu, population effective différée. Le pipeline hydro (ingestion des débits, calculs de productible, endpoints) n''est pas encore actif. Norme de référence internationale pour les essais de réception sur site des machines hydrauliques (turbines, pompes d''accumulation, pompes-turbines), tous types et toutes tailles - impulse, réaction, Pelton, Francis, Kaplan, etc. Couche C des 3 couches Kuma (post-traitement éditorial : convention IEC appliquée aux calculs de productible et performance hydroélectrique). Source hydro structurelle 3/4 du périmètre β2 phase 1 (les 3 autres : `wmo_grdc`, `wwf_hydrosheds`, `wmo_168_2008`). Spécifie les méthodes d''essai applicables, la rédaction des règles de tests, les méthodes de calcul des résultats, et le contenu du rapport final. Détermine si les garanties contractuelles ont été satisfaites. ICS code : 27.140 (Hydraulic energy engineering) - distinct du 27.160 (Solar energy engineering) de `iec_61724_1_2021`. Lignée historique : 1ère édition IEC 41:1963 (« International code for the field acceptance tests of hydraulic turbines », périmètre limité aux turbines hydrauliques, status « Cancelled ») → 2ème édition (datation à confirmer en passe 2) → 3ème édition 1991-11-30 avec élargissement du périmètre aux storage pumps et pump-turbines (titre actuel reflète cet élargissement) ; Corrigendum 1 de mars 1996 intégré dans les copies actuelles. Cette 3ème édition a remplacé deux normes antérieures consolidées : IEC 60198 (1966) et IEC 60607 (1978). Stabilité de la norme : Stability date 2025 selon la fiche IEC officielle. Cette date est une date de revue planifiée (« date à laquelle l''IEC examinera si la norme doit être révisée, reconduite ou retirée »), pas une date de remplacement automatique. À mai 2026, la norme reste pleinement en vigueur, et aucune édition postérieure n''a été publiée à la date de consultation. La revue 2025 peut prendre plusieurs années avant aboutissement à une 4ème édition. À surveiller en passe d''activation phase 2+. Pattern de stabilité prolongée documenté : intertekinform recense une stability date 2017 antérieure à l''actuelle 2025, signe que la norme a déjà été reconduite au moins une fois sans rupture éditoriale (au moins 2017 → 2025 attesté). Confirme la stabilité éditoriale maintenue par revues successives depuis 1991. Convention de code DT-1 : `iec_60041_1991` retient l''organisme producteur (IEC, tutelle internationale), la référence (60041 = série « Field acceptance tests for hydraulic machines »), l''édition millésimée (1991). Cohérent strict avec `iec_61724_1_2021`. Convention transverse normes éditées confirmée par 3ème occurrence (NASA POWER sans année, IEC 61724-1:2021 avec année, WMO-No.8:2024 avec année, IEC 60041:1991 avec année). Pattern stable : code avec année si rupture éditoriale identifiée par millésime, sans année si versionnage continu. Pas de DOI canonique (cohérent IEC). Identifiant canonique = code IEC + édition. ISBN natif IEC `283182222X` (format ISBN-10 pré-2007 ; visible champ « ISBN number » page webstore.iec.ch/en/publication/154 ; dérivées nationales BSI/AFNOR/etc. peuvent avoir leurs propres ISBN distincts, hors périmètre source IEC cf. DT-9 du CdC v2.2). Famille de normes hydro adjacentes (hors scope direct 1-1E, à mentionner pour traçabilité) : IEC 60193:2019 (Hydraulic turbines, storage pumps and pump-turbines - Model acceptance tests) - essais sur modèles laboratoire, distincte de IEC 60041 qui couvre les essais sur site (field acceptance tests) ; IEC 62097-2 (Hydraulic Machines, Radial and Axial - Methodology for Performance Transposition from Model to Prototype, Edition 2) - norme de transposition modèle-prototype. Si Kuma phase 2+ étend les calculs hydro à plusieurs niveaux (modèles + prototypes + transposition), ces normes pourraient mériter des fiches dédiées (DT-X potentielle). Pertinence Kuma - convention applicative phase 2+ : norme directement opérationnelle pour les calculs de productible et performance des centrales hydroélectriques guinéennes : Kaléta (240 MW, opérationnelle 2015), Souapiti (450 MW, opérationnelle 2020+), Amaria (300 MW, en construction mai 2026). Si Kuma calcule le productible de ces centrales (couche C - post-traitement éditorial), l''application de IEC 60041 (méthodes officielles d''essais de performance) sera attendue. Convention applicative à acter en spec préparatoire phase 2+. Accès : paywall IEC Webstore (CHF 450, 478 USD au taux mai 2026). Pages : 419 pages bilingues EN+FR (selon VDE-Verlag et MyStandards) ou 210 pages EN seul (selon IEC Webstore - discordance probable due aux deux versions linguistiques). GF-1 fortement applicable : texte intégral payant ; métadonnées canoniques publiques via page produit IEC. Note licence : la version IEC 60041:1991 est sous copyright IEC (paywall officiel webstore.iec.ch). Une dérivée nationale existe sur Internet Archive (IS/IEC 41:1991, Bureau of Indian Standards) - à NE PAS exploiter dans Kuma tant que la licence n''est pas clarifiée, l''IEC défendant historiquement ses droits d''auteur. Citation académique et utilisation effective : référence IEC officielle uniquement (achat sur webstore.iec.ch). Citation canonique : « IEC 60041:1991, Field acceptance tests to determine the hydraulic performance of hydraulic turbines, storage pumps and pump-turbines, International Electrotechnical Commission, Edition 3.0, November 1991, with Corrigendum 1 of March 1996 ». Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (9, 'wmo_168_2008', 'WMO-No.168 - Guide to Hydrological Practices, Volume I - Hydrology: From Measurement to Hydrological Information (6ème édition, 2008)', NULL, 'World Meteorological Organization (WMO)', 'norme_technique', 2008, '2026-05-10', 'https://library.wmo.int/idurl/4/35804', NULL, '9789263101686', '{"editeur": "World Meteorological Organization (WMO)", "comite_technique": "Standing Committee on Hydrological Services (SC-HYD) sous Services Commission (SERCOM) ; coordination avec INFCOM et Hydrology, Climate and Water Department (HCP) ; anciennement Commission for Hydrology (CHy) avant la réforme WMO 2019", "edition_millesimee": "6ème édition (Vol I 2008, Vol II 2009) ; scope fiche = Vol I 2008 ; 7ème édition en cours de développement (Review Committee établi 2024, group of contributors établi début 2025), non encore publiée à mai 2026"}', 'haute', 'en', 'Source de référence structurelle (hydrologie) : schéma de validation conçu, population effective différée. Le pipeline hydro (ingestion des débits, calculs de productible, endpoints) n''est pas encore actif. Méta-norme métrologique hydrologique pour la phase 1 β2. Couche C des 3 couches Kuma (post-traitement éditorial : conventions WMO hydrométriques appliquées aux mesures pour produire les grandeurs métier hydro). Source hydro structurelle 4/4 et dernière du périmètre β2 phase 1. Scope de la présente fiche : Volume I - Hydrology: From Measurement to Hydrological Information (édition 2008), le plus pertinent pour Kuma phase 1 (mesures hydrométriques : débit, niveaux d''eau, précipitations, évapotranspiration, neige, sédiment, qualité de l''eau, traitement et analyse hydrologiques). Le Volume II - Management of Water Resources and Application of Hydrological Practices (édition 2009) couvre la gestion des ressources en eau et l''application des pratiques hydrologiques - hors scope principal mais mentionné pour traçabilité ; fiche dédiée future possible si extension Kuma vers gestion ressources en eau (DT-X potentielle). Lignée historique : 1ère publication 1965, mises à jour régulières au fil des éditions. 4ème édition (1981/1983) publiée en 2 volumes (Vol I 1981 « data acquisition and processing », Vol II 1983 « analysis, forecasting and other applications ») - approuvée à la 5ème session de la Commission for Hydrology, Ottawa 1976. 5ème édition (1994) publiée comme volume consolidé monolithique + CD-ROM (élargissement de l''audience au-delà des NMHS traditionnels). 6ème édition (2008-2009) réintroduit le découpage en 2 volumes (Vol I 2008 / Vol II 2009) - pattern de découpage non-linéaire dans le temps. 7ème édition en cours de développement par SC-HYD : Review Committee établi en 2024, group of contributors établi début 2025, contenu en cours de revue et mise à jour. Selon SC-HYD officiel : « The revision of the Guide to Hydrological Practices (WMO-No. 168), last published in 2008, has now become a priority. SERCOM will focus mainly on Volume II […], while INFCOM will take the lead in the revision of Volume I ». Publication 7ème édition non datée à mai 2026. Multilingue officiel : English (texte de référence, édition 2008), French (Guide des pratiques hydrologiques, 6ème édition), Spanish (Guía de prácticas hidrológicas), Russian (Руководство по гидрологической практике - édition 2008 mise à jour en 2020 ; cas de versioning linguistique asymétrique, le contenu anglophone restant l''édition 2008 originale). Versions traduites disponibles via la WMO Library. Pas de version Arabe ni Chinoise (contraste avec `wmo_8_2024` qui est dans 6 langues - différence éditoriale entre les guides WMO). Permalinks library.wmo.int : Vol I = `https://library.wmo.int/idurl/4/35804` ; Vol II = `https://library.wmo.int/idurl/4/36066`. Accès libre, PDF téléchargeable directement (pattern WMO cohérent avec `wmo_8_2024`). Pas de DOI canonique : édition de 2008 antérieure à la pratique WMO de DOI''isation (pattern post-2018 observé sur `wmo_8_2024` Volume I). Confirmation transverse de l''observation faite en compilation `wmo_grdc` : le pattern « DOI WMO post-2018 » s''applique aux publications-guides récentes (CIMO Guide 2024) mais pas aux éditions antérieures. La 7ème édition de WMO-No.168 (publication future) sera vraisemblablement DOI''ée. Convention de code DT-1 : `wmo_168_2008` retient l''organisme (WMO, tutelle internationale), la référence (168 = numéro de publication officielle WMO), l''édition millésimée (2008 pour Vol I, scope effectif fiche). Convention transverse normes éditées confirmée par 4ème et dernière occurrence (`iec_61724_1_2021`, `wmo_8_2024`, `iec_60041_1991`, `wmo_168_2008`). Pattern parfaitement stable sur toute la passe : code avec année si rupture éditoriale identifiée par millésime, sans année si versionnage continu (NASA POWER, ECMWF ERA5, WMO/GRDC, WWF/HydroSHEDS, ANM Guinée stations). Citation canonique : « WMO, 2008: Guide to Hydrological Practices. Volume I - Hydrology: From Measurement to Hydrological Information. WMO-No. 168, sixth edition, World Meteorological Organization, Geneva. ISBN 978-92-63-10168-6. » Pertinence Kuma - convention applicative phase 2+ : norme méthodologique de référence pour les conventions hydrométriques applicables aux bassins guinéens (Niger Supérieur, Sénégal, Gambie, Konkouré). Si Kuma calcule des grandeurs métier hydro phase 2+ (débit moyen, débit caractéristique, courbe de tarage, productible hydroélectrique théorique amont, etc.), application des conventions de WMO-No.168 attendue. Convention applicative à acter en spec préparatoire phase 2+. GF-1 non applicable (accès libre direct via library.wmo.int). GF-4 fortement applicable au moment d''activation phase 2+ : surveiller la publication de la 7ème édition (drift CdC futur potentiel similaire à `wmo_8_2024`). Famille adjacente WMO en hydrologie (hors scope direct 1-1E) : Technical Regulations Volume III: Hydrology (WMO-No. 49) - texte régulateur (status « regulation » plus contraignant que le Guide) ; Manuals on Hydrology and Water Resources (série WMO-Nos. 519, 686, etc.) - manuels opérationnels spécialisés (par exemple : Manual on Stream Gauging WMO-No. 519, Operational Methods for the Measurement of Sediment Transport WMO-No. 686). Si Kuma phase 2+ étend les pratiques hydrométriques opérationnelles, ces manuels pourraient mériter des fiches dédiées (DT-X potentielle). Consulté le 2026-05-10.', true, NULL, '2026-09-17 06:04:12.544422+00', NULL, '2026-09-17 06:04:12.544422+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (10, 'kuma_calculs', 'Kuma Science - Couche de calculs internes', '{"Kuma Science"}', 'Kuma Science', 'auteur_kuma', NULL, NULL, NULL, NULL, NULL, NULL, 'haute', 'fr', 'Source synthetique representant la couche editoriale Kuma. Utilisee comme source primaire des series methode_collecte=''calcul_derive'' (HEP en 1-5 ; futures grandeurs calculees Kuma en 1-6+). Auto-evaluation fiabilite=''haute'' coherente avec la doctrine editoriale phase 1 (Kuma engage son autorite editoriale sur la correction du calcul, cf. cadrage phase 1 Principe 1). Acknowledgement des sources amont (par exemple gin_*_ghi_nasa_power_* pour HEP) trace par commentaire_editorial de chaque serie calculee.', true, NULL, '2026-09-17 06:04:21.76913+00', NULL, '2026-09-17 06:04:21.76913+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (11, 'sarah3_monthly', 'PVGIS-SARAH3 ICDR : Surface Solar Radiation Data Set - Heliosat, chaine MAGICSOL CM SAF / EUMETSAT (Edition 3)', '{"CM SAF / EUMETSAT"}', 'Satellite Application Facility on Climate Monitoring (CM SAF), EUMETSAT ; portage applicatif PVGIS par le Joint Research Centre (JRC) de la Commission europeenne.', 'base_donnees', NULL, NULL, 'https://re.jrc.ec.europa.eu/api/v5_3/MRcalc', NULL, NULL, NULL, 'haute', 'en', 'Chaine de retrieval MAGICSOL (Heliosat modifie Hammer et al. 2003 + gnu-MAGIC Mueller et al. 2009 + SPECMAGIC Mueller et al. 2012). Validee Afrique de l''Ouest par Sawadogo et al. 2023 (Renewable Energy 216:119066) et Kakou et al. 2025 (Remote Sensing 17(6):998). Validation Europe par Urraca et al. 2017, 2018. Edition 3 deployee depuis 2024 ; ICDR (Interim CDR) couvre 2021-present, complement de CDR (Climate Data Record) 1983-2020. Retenue en 1-7a comme source de reference inter-source pour ecart_relatif_referentiel (cf. note methodologique amont PR #53).', true, NULL, '2026-09-17 06:04:24.794296+00', NULL, '2026-09-17 06:04:24.794296+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (12, 'ecmwf_era5_land', 'ECMWF ERA5-Land - Land component of the ERA5 reanalysis (Copernicus Climate Change Service)', NULL, 'European Centre for Medium-Range Weather Forecasts (ECMWF)', 'base_donnees', 2019, '2026-06-16', 'https://cds.climate.copernicus.eu/datasets/reanalysis-era5-land', '10.24381/cds.68d2bb30', NULL, '{"forcage": "ERA5_interpole_MIR", "licence": "CC-BY (ex Licence to use Copernicus Products, remplacee 2025-07-02)", "grille_api": "0.1deg_regulier", "produits_utilises": ["monthly-means", "hourly (agrege en journalier)"], "resolution_native": "9km_TCo1279_non_servie_par_api", "couverture_temporelle": "1950-present"}', 'haute', 'en', 'Réanalyse land-only haute résolution, replay de la composante terrestre d''ERA5 forcée par ERA5 (interpolation MIR depuis 2020). Référence : Muñoz-Sabater et al. (2021), « ERA5-Land: a state-of-the-art global reanalysis dataset for land applications », ESSD 13, 4349-4380, DOI 10.5194/essd-13-4349-2021. Distribution CDS Copernicus. Le DOI 10.24381/cds.68d2bb30 cible le produit monthly-means ; le produit hourly (agrégé en journalier côté Kuma) porte un DOI distinct. Attribution requise (CC-BY) : « Generated using Copernicus Climate Change Service Information [Year] ». Vague 4 Lot A : co-localisation (D-29) et altitude (D-24) sur les 6 villes pilotes. Consulté le 2026-06-16.', true, NULL, '2026-09-17 06:04:36.112171+00', NULL, '2026-09-17 06:04:36.112171+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (13, 'cams_radiation', 'CAMS Radiation Service - solar radiation time-series (Copernicus Atmosphere Monitoring Service)', NULL, 'Copernicus Atmosphere Monitoring Service (CAMS) / ECMWF', 'base_donnees', 2017, '2026-06-16', 'https://ads.atmosphere.copernicus.eu/datasets/cams-solar-radiation-timeseries', '10.24381/5cab0912', NULL, '{"store": "ADS (Atmosphere Data Store)", "licence": "CC-BY (attribution Copernicus/CAMS requise)", "methode": "Heliosat-4 (all-sky) + McClear (clear-sky)", "dataset_id": "cams-solar-radiation-timeseries", "unite_source": "Wh/m2 integres sur le pas (StatisticalMeasure sum)", "sky_type_ingere": "observed_cloud (all-sky)", "grandeur_ingeree": "BNI (DNI all-sky, aerosol-corrige)", "pas_temporel_ingere": "1month (agregat mensuel natif)", "couverture_temporelle": "2004-02 a J-1 (Meteosat MSG/IODC)"}', 'haute', 'en', 'Service de rayonnement solaire CAMS (Copernicus Atmosphere Monitoring Service) : méthode Heliosat-4 pour le ciel réel (all-sky) et McClear pour le ciel clair, à partir des images Meteosat (MSG/IODC) et des champs d''aérosols / vapeur d''eau CAMS. Référence méthode : Qu et al. (2017), « Fast radiative transfer parameterisation for assessing the surface solar irradiance: the Heliosat-4 method », Meteorologische Zeitschrift 26(1), 33-57. DOI du dataset : 10.24381/5cab0912 (catalogue ADS Copernicus, section citation de la page dataset). Distribution ADS Copernicus. Attribution requise (CC-BY) : « Generated using Copernicus Atmosphere Monitoring Service Information 2026 ». Vague 4 Lot B : DNI all-sky aérosol-corrigé (BNI), 3ᵉ référence d''écart inter-source (enjeu Harmattan). Consulté le 2026-06-16.', true, NULL, '2026-09-17 06:04:41.826608+00', NULL, '2026-09-17 06:04:41.826608+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (14, 'esmap_wapp', 'ESMAP/WAPP - Solar resource measurement campaign in West Africa (stations sol Tier-1, Solar Development in Sub-Saharan Africa)', NULL, 'World Bank / ESMAP / WAPP (EEEOA) ; operateur CSP Services GmbH', 'base_donnees', NULL, '2026-06-17', 'https://energydata.info/dataset/guinea-solar-radiation-measurement-data', NULL, NULL, '{"store": "energydata.info (World Bank Group)", "licence": "CC-BY-4.0", "campagne": "Solar Development in Sub-Saharan Africa (ESMAP/WAPP)", "operateur": "CSP Services GmbH", "instruments": "Kipp & Zonen CMP10 (GHI/DHI), CHP1 (DNI), NRG 40C/200M, Vaisala PTB110", "stations_guinee": ["Kankan", "Tarambaly"], "grandeur_ingeree": "GHI (agrege horaire, terrain-lite Lot A)", "niveaux_qc_source": "donnees QC fournisseur (CSP Services)", "pas_temporel_source": "1 minute (UTC+0)", "annee_publication_statut": "a confirmer (rapports 2021 install / 2022 / 2024 final)"}', 'haute', 'en', 'Campagne de mesures solaires au sol ESMAP/WAPP (World Bank / West African Power Pool), stations meteorologiques automatiques Tier-1 (operateur CSP Services GmbH) mesurant GHI/DNI/DHI + meteo au pas 1 minute. Deux stations en Guinee : Kankan (10.36465 N / -9.30466 E, 375 m, co-localisee < 2 km du pilote gin_kankan) et Tarambaly (11.356 N / -12.137 W, 860 m, Fouta-Djalon 16 km de Labe). Pyrheliometre DNI thermopile CHP1, pyranometres CMP10 GHI/DHI (Kipp & Zonen). Licence CC-BY-4.0 (energydata.info, jeu Guinee, consulte le 2026-06-17). Attribution requise : « World Bank / ESMAP / WAPP - Solar resource measurement campaign in West Africa (CC-BY-4.0) ». Source en appui de la couche confiance A (mesure sol) : terrain-lite GHI Lot A, premiere grandeur Kuma en confiance A via la regle R3. Annee de publication du jeu a confirmer (non inventee).', true, NULL, '2026-09-17 06:04:42.439361+00', NULL, '2026-09-17 06:04:42.439361+00', NULL);
INSERT INTO public.sources (id, code, titre, auteurs, organisation, type_source, annee_publication, date_consultation, url, doi, isbn, metadonnees, fiabilite, langue, notes, actif, desactive_le, cree_le, cree_par, modifie_le, modifie_par) VALUES (15, 'cams_eac4', 'CAMS EAC4 - ECMWF Atmospheric Composition Reanalysis 4 (cams-global-reanalysis-eac4)', NULL, 'ECMWF / Copernicus Atmosphere Monitoring Service (CAMS)', 'base_donnees', NULL, '2026-06-18', 'https://ads.atmosphere.copernicus.eu/datasets/cams-global-reanalysis-eac4', NULL, NULL, '{"store": "ADS (Atmosphere Data Store, Copernicus)", "licence": "Copernicus (CC-BY)", "note_hsu": "le modele HSU consomme les PM de surface, pas l''AOD", "conversion": "kg/m3 (natif) -> ug/m3 (x 1e9)", "dataset_id": "cams-global-reanalysis-eac4", "periode_reelle": "2021-01-01 a 2025-08-31", "agregation_kuma": "moyenne journaliere des pas 3-horaires (concentration intensive)", "latence_reanalyse": "10 mois (juin 2026 : EAC4 borne a aout 2025)", "resolution_grille": "0,75 deg", "variables_ingerees": ["pm2.5 (pm2p5)", "pm10"], "pas_temporel_source": "3-horaire (00/03/06/09/12/15/18/21 UTC)", "annee_publication_statut": "reanalyse continue ; reference methodologique Inness et al. 2019", "reference_methodologique": "Inness, A. et al. (2019), The CAMS reanalysis of atmospheric composition, Atmos. Chem. Phys. 19, 3515-3556, doi:10.5194/acp-19-3515-2019"}', 'haute', 'en', 'Reanalyse de composition atmospherique EAC4 (ECMWF Atmospheric Composition Reanalysis 4, CAMS), servie par l''ADS Copernicus. Fournit PM2.5 et PM10 de surface (kg/m3 natif, converti ug/m3) au pas 3-horaire, agreges en moyenne journaliere par Kuma. Entree particules du modele de salissure HSU (proxy taux_salissure_proxy, Vague 5 Lot C) : le HSU consomme les PM, pas l''AOD. Confiance B derivee (modele satellitaire, pas mesure directe -> R3 ne donne pas A). Grille grossiere 0,75 deg (caveat L-SOIL-4). Couverture reelle 2021-01-01 a 2025-08-31 (latence de reanalyse 10 mois). Licence Copernicus (CC-BY) ; attribution : Generated using Copernicus Atmosphere Monitoring Service Information 2026. DOI dataset et annee de publication non confirmes (non inventes) ; reference methodologique Inness et al. 2019 (doi:10.5194/acp-19-3515-2019).', true, NULL, '2026-09-17 06:04:55.363582+00', NULL, '2026-09-17 06:04:55.363582+00', NULL);
